(window.MEANINGS_BY=window.MEANINGS_BY||{}).hi=["महान नेमतों का दाता। यह विशेषता केवल अल्लाह के लिए विशिष्ट है, जिसका अर्थ है कि वह सभी पर — काफिर और मोमिन दोनों पर — दयालु है और नेमतें प्रदान करता है। रहमान की विशेषता सर्वोच्च अल्लाह के अलावा किसी और के लिए उपयोग नहीं की जा सकती।","सूक्ष्म नेमतों का दाता।\n\nयह विशेषता अधिक विशिष्ट है, जिसका अर्थ है 'क़यामत के दिन केवल विश्वासियों पर दया दिखाना'। यह नाम अल्लाह के अलावा अन्य लोगों के लिए भी प्रयोग किया जा सकता है, जिनमें पैगंबर (शांति उन पर हो) भी शामिल हैं। अल्लाह का नाम रहीम अक्सर तव्वाब, गफूर, रऊफ़, वदूद, अज़ीज़ की विशेषताओं के साथ उल्लिखित होता है, क्योंकि रहीम विशेष दया है, जबकि रहमान सामान्य दया है।","सब कुछ का स्वामी। मलिक सच्चा स्वामी है। उसके अलावा कोई स्वामी नहीं है। इसलिए बंदे केवल उसी के बंदे हो सकते हैं। एक बंदे के कभी दो स्वामी नहीं हो सकते। इसलिए लोगों को अपने जैसे इंसानों का नहीं, बल्कि एकमात्र स्रष्टा, सच्चे मलिक का बंदा होना चाहिए।","सभी दोषों से मुक्त, हर अपूर्ण विशेषता से परे। पूर्ण पवित्रता और पूर्ण शुद्धता केवल अल्लाह के लिए विशिष्ट है।","सभी दोषों से मुक्त। इसका अर्थ शांति, सुकून और आराम देने वाला भी है। 'सलाम' विशेषता के माध्यम से अल्लाह अपने बंदों को शांति, सुरक्षा और सुकून प्रदान करता है।","अल-मुमिन — विश्वास और सुरक्षा देने वाला।","सब कुछ को समाहित करने वाला। अल्लाह अपने बंदों की सभी अवस्थाओं का गवाह है। उससे कुछ भी छिपा नहीं रहता।","सबसे विजयी। कोई भी चीज़ उस पर विजय नहीं पा सकती। समस्त प्रतिष्ठा केवल उसी की है। शक्ति और सामर्थ्य की प्रतिष्ठा भी उसी की है — उस पर विजय नहीं पाई जा सकती। रोकने की प्रतिष्ठा भी उसी की है, वह किसी का मुहताज नहीं। क्रोध और विजय की प्रतिष्ठा भी उसी की है, उसकी अनुमति के बिना कुछ भी नहीं चलता।","'अल-जब्बार' विशेषता का अर्थ है वह उच्चतम सत्ता, जिसके सामने सब विनम्र हो जाते हैं। वह गरीबों को आवश्यकता से मुक्त करता है, हर पीड़ित व्यक्ति का बोझ हल्का करता है, संकट में पड़े लोगों को धैर्य और दृढ़ता प्रदान करता है, और यदि वे अपने कर्तव्यों को पूरा करें, तो संकट के बदले उन्हें विशाल प्रतिफल देता है। टूटे हुए हृदय उसी के कारण ठीक होते हैं। दुआ में 'अल्लाहुम्मा उज्बुर्नी' शब्द बंदे के सुधार और उसे हानि पहुँचाने वाली हर चीज़ को दूर करने की सच्चाई है।","अल-मुतकब्बिर — जिसकी महानता और भव्यता असीम है। उसके सामने सभी सेवक हैं। वह हर बुराई और दोष से ऊपर है, और अपने बंदों पर अत्याचार करने से भी ऊपर है। जो उसके साथ महानता में प्रतिस्पर्धा करे, वह उसे कुचलता और दंडित करता है।","जिस चीज़ का कोई मूल या समानता नहीं है, उसे उचित माप में बनाने वाला। अल्लाह सृष्टि बनाने से पहले भी 'सृष्टिकर्ता' की विशेषता रखता था। उसने सृष्टि बनाने के बाद 'सृष्टिकर्ता' नाम प्राप्त नहीं किया। अल-खालिक पूर्ण सृष्टिकर्ता है।","शून्य से अस्तित्व में लाने वाला। अल-बारी की रचना में कोई दोष नहीं है।","अल-मुसव्विर — सृष्टियों को आकार देने वाला, हर चीज़ को उसका विशिष्ट रूप देने वाला।","बहुत क्षमा करने वाला, अपनी कृपा से बंदों की गलतियों और पापों को माफ करने वाला।","सभी सृष्टियों को अपनी पकड़ में रखने वाला, उन्हें अपने आदेश से चलाने वाला और अपनी शक्ति से वशीभूत करने वाला। अल्लाह अपनी प्रतिष्ठित सत्ता के साथ उन लोगों पर कठोर दंड लगाता है जो उसकी एकता को दर्शाने वाले संकेत उतरने के बाद भी उसे नकारते हैं, और उन पर जो उसकी सृष्टि पर अत्याचार करते हैं।","अनगिनत नेमतें देने वाला। वहाब का अर्थ है बहुत अधिक देने वाला, कृपा करने वाला, प्रदान करने वाला। अरबी में 'फ़अ्आल' रूप जोर देने के लिए प्रयुक्त होता है। अल्लाह वहाब है। वह अपने बंदों को अपनी महान कृपा से प्रदान करता है। उन्हें लगातार नेमतें देता है। उन्हें भरपूर उपहार देता है। हर चीज़ का खजाना, आकाशों और धरती का साम्राज्य, और सभी कार्यों की बाग़डोर अल्लाह के हाथ में है। अल्लाह अपने राज्य में जैसे चाहे व्यवहार करता है।","प्रचुर जीविका देने वाला। जीविका और उसके साधनों का सृजनकर्ता। अर-रज़्ज़ाक़ अपनी सृष्टियों को किसी भी बोझ, कठिनाई के बिना और किसी की सहायता मांगे बिना जीविका प्रदान करता है।","बहुत सी चीज़ों को खोलने वाला। अपने बंदों के लिए अपनी दया का खजाना खोलने वाला।","हर चीज़ को जानने वाला। जो हुआ और जो होगा, पहला और आख़िरी, प्रकट और छिपा हुआ — सब कुछ जानने वाला।","आत्माओं को ले लेने वाला। जिसे चाहे उसकी जीविका रोक लेने वाला। हृदयों को संकुचित करने वाला (क़ब्द़ का अर्थ है पकड़ना, रोकना)।","आत्माओं को विशालता में मुक्त करने वाला। जिसे चाहे उसकी जीविका विस्तृत करने वाला। हृदयों को विस्तृत करने वाला।","नीचा दिखाने वाला। उदाहरण के लिए, काफिरों और पापियों के दर्जे को उन्हें अपमानित करके नीचा करता है।","ऊपर उठाने वाला। उदाहरण के लिए, मोमिनों और परहेज़गारों के दर्जे को ऊंचा करता है, उन्हें सम्माननीय और आदरणीय बनाता है।","सम्मान देने वाला। जिसे चाहे सही रास्ते पर लगाकर उसे सम्मानित करता है।","अपमानित करने वाला। जिसे चाहे टेढ़े रास्ते पर चलने के कारण अपमानित करता है।","सब कुछ सुनने वाला। वह भाषाओं की विविधता और आवश्यकताओं की भिन्नता के बावजूद सभी आवाज़ें सुनता है। उसके सुनने में गुप्त बात और खुली बात बराबर है। अल्लाह की श्रवण शक्ति सभी आवाज़ों को समेटे हुए है। उसके लिए आवाज़ें आपस में नहीं मिलतीं। कुछ आवाज़ें सुनना उसे दूसरी आवाज़ें सुनने से नहीं भटकाता। विनतियों की विविधता उसे भ्रमित नहीं करती।","सब कुछ देखने वाला। वह सभी दृश्य चीज़ें देखता है, हर चीज़ देखता है चाहे वह अत्यंत छोटी और सूक्ष्म हो। वह अंधेरी रात में पत्थर पर चलती काली चींटी को भी देखता है। वह सात परतों वाली धरती के नीचे की चीज़ें उसी तरह देखता है जैसे सात आसमानों के ऊपर की चीज़ें देखता है। वह पलकों की हरकत और आंखों की बेवफाई भी देखता है।","अल-हकम, अल-हिकम और अल-हाकिम शब्दों का एक ही अर्थ है। यह महान नाम संकेत करता है कि अल्लाह के लिए संपूर्ण निर्णय और संपूर्ण ज्ञान स्थापित है। अल्लाह की संपूर्ण बुद्धिमत्ता उसकी सृष्टि, उसके आदेशों और उसकी शरीअत में स्थापित है — वह हर चीज़ को उसके उचित स्थान पर रखता है। कोई अल्लाह से 'क्यों' नहीं पूछता। कोई अल्लाह की बुद्धिमत्ता के विरुद्ध एक शब्द भी नहीं कह सकता। अल्लाह की पूर्णता और निर्णय केवल उसी के हैं। वह अपने बंदों के बीच जो चाहे उससे फैसला करता है। उसके फैसले को पलटने या जांचने वाला कोई नहीं।","पूर्णतः न्यायी। अल्लाह इस दुनिया और क़यामत के दिन अपने बंदों के बीच न्याय के साथ फैसला करता है। वह किसी पर एक कण भर भी अत्याचार नहीं करता। किसी पर दूसरे का गुनाह नहीं लादता। बंदे के गुनाह से अधिक सज़ा नहीं देता। हकों को उनके मालिकों को लौटाकर फैसला करता है।","लतीफ़ के दो अर्थ हैं। पहला — सभी चीज़ों के सूक्ष्म और बारीक पहलुओं को जानने वाला। अर्थात अत्यंत सूक्ष्म बातें जानने वाला, यहाँ तक कि रहस्यों को, दिलों के भीतर की बातों को और छिपी हुई चीज़ों को। दूसरा अर्थ — अत्यंत कृपालु। अर्थात अपने बंदों और प्रियजनों तक विभिन्न लाभ, अपनी कृपा और उदारता से, उन रास्तों के द्वारा पहुंचाने वाला जिन्हें वे जानते नहीं। उदाहरण के लिए, पैगंबर यूसुफ (उन पर शांति हो) और पैगंबर मूसा (उन पर शांति हो) के हालात इसके उदाहरण हैं। इन दोनों कहानियों में भी मामले अत्यंत गोपनीयता और सूक्ष्मता से आगे बढ़े और अंततः अल्लाह की दया मोमिन बंदों तक पहुंची।","हर चीज़ से पूरी तरह सूचित। यानी उनका ज्ञान छुपी हुई चीज़ों, रहस्यों, दिलों के अंदर छुपी चीज़ों, दानों के अंदर की छुपी चीज़ों और कणों को भी जानता है, और बारीक पहलुओं को जानते हुए सूक्ष्म मामलों से वाकिफ है। यह नाम अत्यंत सूक्ष्म, नाज़ुक, बहुत छोटी और बहुत छुपी चीज़ों को जानने से संबंधित है।","इसका अर्थ है जिसका क्रोध नहीं भड़कता और जो दंड देने में जल्दबाज़ी नहीं करता। वह अपने बंदों के प्रति सहनशील है। अल्लाह आज्ञाकारी बंदों को इबादत और सवाब बढ़ाने के लिए मोहलत देता है। पापी बंदों को भी शायद वे आज्ञाकारिता और नेक अमल की ओर लौटें, इसलिए मोहलत देता है। अगर वह बंदों को जल्दी सज़ा देता, तो कोई भी सज़ा से नहीं बचता। लेकिन अल्लाह सहनशील, क्षमाशील और मोहलत देने वाला, जल्दबाज़ी न करने वाला है। इस प्रकार, सहनशीलता के कारण काफिरों को दंडित करने में देरी करता है। अपनी कृपा से मोमिनों के सवाब में भी देरी करता है। निष्कर्ष में, सहनशीलता वाला अज़ाब और सज़ा को टालता है और बंदों के गुनाहों के कारण उन पर अपनी कृपा और नेमत बंद नहीं करता। बल्कि आज्ञाकारियों को रोज़ी देता है वैसे ही नाफ़रमानों को भी रोज़ी देता रहता है, भले ही उनके बीच बुद्धि के अनुसार अंतर हो।","इतना भव्य और महान कि बुद्धि इसकी कल्पना नहीं कर सकती। अहंकार, घमंड — यानी खुद को सबसे बड़ा समझना — और महानता केवल अल्लाह के लिए विशिष्ट है। यदि कोई 'मैं महान हूं' कहकर महानता का दावा करे, तो अल्लाह उसे जहन्नम में डालेगा। बंदे अल्लाह की विशेषता 'अज़मत' की मात्रा और सार को नहीं जान सकते। यदि एक मुसलमान जाने कि हर चीज़, चाहे कितनी भी बड़ी हो, अल्लाह की अज़मत के सामने छोटी हो जाती है, और इस पर ईमान लाए, तो वह उसके सामने विनम्र होगा और सभी प्रकार की इबादत केवल अल्लाह के लिए करेगा, यह विश्वास रखते हुए कि केवल वही इन इबादतों का हक़दार है।","बहुत अधिक क्षमा करने वाला। अल-ग़ाफ़िर और अल-ग़फ़्फ़ार का भी यही अर्थ है। लेकिन अल-ग़फ़ूर जोर देने के लिए उपयोग किया जाता है। 'ग़फ़ूर' शब्द का अर्थ है ढकना, आड़ करना। अल्लाह की ओर से क्षमा का मतलब है बंदे को अज़ाब से बचाना। अल्लाह की क्षमा तुम्हारे और अज़ाब के बीच की रुकावट है। इसलिए बंदे की विशेषता गुनाह करना है, और अल्लाह की शान उन्हें माफ करना है। गुनाहों की माफी के लिए उसने तुम्हें इस्तिग़फार करने का आदेश दिया। इस्तिग़फार का आदेश देना इसलिए है क्योंकि वह इंसान में कमज़ोरी और ग़फलत के होने को जानता है। माफी (यानी गुनाहों की क्षमा) मानवता की कमज़ोरी का इलाज है। अगर अल्लाह की ओर से माफी न होती, तो हम अपने गुनाहों को कैसे मिटाते, किस मुंह से अपने रब से मिलते?!","थोड़े अमल पर भी बहुत सवाब देने वाला। अश-शाकिर और अश-शकूर दोनों विशेषताएं अल्लाह के नामों में से हैं, जिनका अर्थ है कि वह अमल करने वाले बंदों की मेहनत को व्यर्थ नहीं करता और उन्हें बहुत सवाब देता है। बल्कि कई गुना बढ़ाकर देता है। क्योंकि अल्लाह नेकी करने वालों के अमल को बर्बाद नहीं करता। अल्लाह ने अपनी किताब और अपने रसूल की सुन्नत में बताया है कि वह एक नेकी को दस गुना से सात सौ गुना तक बढ़ाता है। यही अल्लाह की ओर से बंदों के लिए शुक्रगुज़ारी है। वह मोमिनों को अपनी रज़ा के लिए तौफीक देता है, फिर उसके शुक्र में ऐसी नेमतें अता करता है जो न आंख ने देखी, न कान ने सुनी और न इंसान के दिल ने महसूस की। ऐसा करना उसकी ज़िम्मेदारी नहीं थी। यह उसने केवल अपनी करम और सखावत से अपने ऊपर लाज़िम किया। अल्लाह पर यह फर्ज़ नहीं था कि वह फरमांबरदारों को सवाब दे और गुनाहगारों को सज़ा दे। बल्कि सवाब देना उसके फज़ल और रहमत से है। और अज़ाब देना उसके इंसाफ और हिकमत के मुताबिक है।","पद की श्रेष्ठता में असीम। अल्लाह अपने अस्तित्व की श्रेष्ठता से अली है। वह अर्श पर विराजमान है और सभी ब्रह्मांडों से ऊपर है, उनसे अलग है। वह महान पद वाला अली और परम उच्च है। अल्लाह के गुण उच्च और महान हैं। उसके गुण इतने महान हैं कि किसी का कोई गुण उनके निकट नहीं आता और न उनके जैसा है। बल्कि बंदों में अल्लाह के गुणों में से एक गुण को भी पूरी तरह समझने, जानने और समझ पाने की क्षमता नहीं है। वह वशीकरण में श्रेष्ठ, अर्थात क्रोध में श्रेष्ठ अली और परम उच्च है। अल्लाह ने सब कुछ वश में किया है। सभी ब्रह्मांड उसके आगे समर्पित हैं, सभी जीवों की बागडोर उसके हाथ में है। उनमें से हर एक चाहे हरकत करे, ठहरे या ख़ामोश रहे, अल्लाह की इजाज़त से ही करता है। अल्लाह जो चाहता है वही होता है, जो नहीं चाहता वह नहीं होता। अल्लाह के अपनी सृष्टि से ऊपर होने पर ईमान लाना बंदे में अल्लाह की महिमा, उसके सामने विनम्रता और दीनता के साथ खड़े होने, अल्लाह को हर कमी और दोष से पाक मानने, उसकी इबादत में इख़लास, और अल्लाह के सिवा साझीदार और बराबर ठहराने से दूरी पैदा करता है और इनका कारण बनता है।","हर चीज़ से बड़ा। अल्लाह अलियुल-कबीर है। यानी जिसकी ज़ात, पद और क्रोध महान है, जो हर चीज़ से बड़ा है। जिसके लिए घमंड विशेषता है और महानता वर्णन है। अल्लाह ने हदीस कुद्सी में कहा: 'प्रतिष्ठा मेरा लुंगी है और घमंड मेरी चादर है (यानी ये दोनों गुण मुझे विशिष्ट हैं)। जो इन गुणों में मुझसे झगड़े, उसे मैं अज़ाब दूंगा।' (इमाम मुस्लिम की रिवायत)। घमंड, अहंकार — यानी खुद को सबसे बड़ा समझना — और महानता केवल अल्लाह के लिए विशिष्ट है।","सब चीज़ों का पूर्ण रक्षक। क़ुरआन की सूरह हूद में कहा गया है: 'बेशक मेरा रब हर चीज़ का निगहबान है।' ये दो महान नाम अल्लाह के रक्षा और संरक्षण के गुण का संकेत करते हैं। अल्लाह का अपने बंदों को रक्षा करना दो प्रकार का है: सामान्य और विशेष। सामान्य रक्षा: अल्लाह बंदों को भोजन, पेय और वायु प्रदान करके, उनकी ज़रूरतों और आवश्यकताओं की ओर मार्गदर्शन करके, और उनसे बुराइयों, हानियों और अप्रिय चीज़ों को दूर करके उनकी रक्षा करता है। इस रक्षा में अच्छे-बुरे, जानवर और दूसरी चीज़ें भी साझा हैं। अल्लाह ने आदम की संतान की रक्षा के लिए फ़रिश्ते नियुक्त किए हैं। विशेष रक्षा: इससे अल्लाह अपने वलियों और मित्रों की ईमान को भ्रमित करने वाले संदेहों, फ़ितनों और विनाशकारी वासनाओं से रक्षा करता है। तुम अल्लाह की हिफ़ाज़त करो — उसकी सीमाओं का उल्लंघन न करके, उसकी मनाही से रुककर और उसके आदेशों का पालन करके। तब अल्लाह तुम्हारी जान, दीन, माल और बाल-बच्चों में तुम्हारी रक्षा करेगा।","सभी भौतिक और आध्यात्मिक जीविका का सृजनकर्ता। मुक़ीत का अर्थ है: पर्याप्त करने वाला, रक्षक, जीविका देने वाला, हिस्सा देने वाला, सर्वशक्तिमान। यह नाम इन सभी को समेटे हुए है। इस प्रकार, वह बंदों की अवस्थाओं और उनकी ज़रूरतों को समाहित करता है। वह हर चीज़ पर सक्षम है। वह अपनी सृष्टि में से जिसे चाहे उसके दिल को ज्ञान और ईमान से समृद्ध करता है। अल-मुक़ीत भौतिक और आध्यात्मिक जीविका का सृजनकर्ता है, अपने बंदों को पोषण देने वाला और पालने वाला है। उसने आत्मा और शरीर को शक्ति देने वाला पोषण बनाया और अकेले ही सभी जीवित प्राणियों को जीविका प्रदान करता है। उसने लोगों के जीविका खोजने के साधन भी बनाए और सभी को अपनी ज़रूरतें पूरी करने के लिए सही और शुद्ध साधनों का उपयोग करने का आदेश दिया। इसके अलावा, अल-मुक़ीत दिलों को तजल्ली के नूर से रोशन करने वाला और आध्यात्मिक पोषण प्रदान करने वाला है।","पर्याप्त करने वाला और क़यामत के दिन बंदों का हिसाब करने वाला। अल्लाह पूर्णतः पर्याप्त है। यह विशेषता केवल अल्लाह के लिए उपयुक्त है। जब भी कोई इंसान तुम्हें कुछ देता है, तुम फिर भी किसी और चीज़ के मुहताज रहते हो। लेकिन यदि अल्लाह तुम्हें सुरक्षा, बुद्धि और ज्ञान, स्वास्थ्य और तंदुरुस्ती, परिवार की नेमत, नेक संतान, ज़रूरत से अधिक चीज़ें, आत्मिक शांति, संतुष्टि, समृद्ध जीवन शैली और सुखद भौतिक जीवन प्रदान करे, तो उसका प्रदान भौतिक और आध्यात्मिक जीवन के हर पहलू के लिए पर्याप्त है। इस प्रकार, यदि बंदे अल्लाह से विनती करें, उससे मदद मांगें और उस पर भरोसा करें, तो वह निश्चित रूप से पर्याप्त होगा। अबू हामिद ग़ज़्ज़ाली ने कहा: 'अल-हसीब पर्याप्त है। जिसके लिए अल्लाह काफी हो, वही काफी है। कभी-कभी कोई इंसान तुम्हारी सेवा करता है लेकिन तुम अभी भी उससे बड़ी सेवा के मुहताज रहते हो। वह मदद करता है लेकिन अब तुम्हें इलाज की ज़रूरत होती है। लेकिन यदि अल्लाह तुम्हारा काम अपने हाथ में ले ले — ऐसा नहीं है। अल्लाह के साथ रहो, तुम निश्चित रूप से उसका समर्थन देखोगे।'","अपने गुणों में महानता रखने वाला। जब मोमिन 'अल्लाह' नाम का उपयोग करते हैं, तो शिष्टाचार के रूप में 'अल्लाह जल्ला व जलालुहू' या 'अल्लाह अज़्ज़ा व जल्ला' कहते हैं, जिसका अर्थ है 'अल्लाह सर्वशक्तिमान और महान है', 'अल्लाह शक्तिशाली और महान है'। इस प्रकार, अल-जलील का अर्थ प्रतिष्ठा, आत्मनिर्भरता और पवित्रता भी है। अल-जलील का अर्थ 'आदेश देने और मना करने का अधिकार रखने वाला' भी है। वह इतना महान है कि प्रत्येक महानता उसके सामने तुच्छ है और प्रत्येक ऊँचाई उसके सामने नीची है।","बिना मांगे, बिना किसी प्रतिफल के, बहुत कुछ प्रदान करने वाला। विरोधाभासों से मुक्त। उदार कार्यों और गुणों का स्वामी। यह उदार और दानशील विशेषता संकेत करती है कि यह अल्लाह की स्थायी विशेषता है। 'करम' शब्द सभी भलाइयों और प्रशंसनीय कार्यों को समेटता है — इसका अर्थ केवल देना नहीं है, बल्कि देने का सबसे संपूर्ण अर्थ समझा जाता है। इसीलिए विद्वानों ने इस नाम के अर्थ के बारे में बहुत कुछ कहा है: भलाई और उपहार बहुत अधिक, भलाई और उदारता स्थायी, पद महान, प्रतिष्ठा बड़ी, दोषों और आपदाओं से मुक्त, सम्मान देने वाला, नेमत देने वाला, दया करने वाला, बिना प्रतिफल के देने वाला, बिना कारण के देने वाला, ज़रूरतमंद और गैर-ज़रूरतमंद दोनों को देने वाला, वादा पूरा करने वाला, बड़ी-छोटी सभी ज़रूरतें उसके सामने पेश की जाने वाली, उस पर भरोसा करने वाले को व्यर्थ न करने वाला। इस नाम के अर्थ के बारे में कही गई बातों में से एक यह भी है: «गुनाहों को माफ़ करने और बुराइयों को बख़्श देने वाला»।","एक कण भी छोड़े बिना निगरानी करने वाला। यदि कोई मोमिन बंदा इस नाम पर ईमान लाए, तो इसका प्रभाव उसके ईमान, चरित्र और आचरण में स्पष्ट रूप से दिखाई देगा। जब तुम महसूस करो कि तुम्हें देखा जा रहा है, तो यह खुद को सुधारने और अनुशासित करने का अवसर है। जब एक व्यक्ति महसूस करता है कि उसके जैसा कोई उसे देख रहा है, तो वह अनुशासित हो जाता है — तो जब वह महसूस करे कि जगत के पालनकर्ता उसे देख रहे हैं, तो क्या होगा?! रक़ीब बंदों की अवस्थाओं की निगरानी करता है — उनका मुंह फेरना और पीठ करना, उनकी ईर्ष्या, नफरत और घृणा, उनकी ईमानदार नीयत, दूसरों से प्रेम, दूसरों से खुद को ऊँचा समझना, और दूसरों के साथ चालबाज़ी। इस प्रकार, जब भी कोई व्यक्ति एक शब्द बोलता है, मन में कुछ सोचता है, या कोई कार्य करता है, वह निश्चित रूप से उसे देखता और जानता है।","दुआओं को क़बूल करने वाला। मुजीब मांगने वाले की मांग पूरी करता है, दुआ करने वाले की दुआ क़बूल करता है, और मजबूर हो गए व्यक्ति की ज़रूरत को पूरा करता है। अल्लाह इंसान की ज़रूरत को उसके मांगने से पहले ही जानता है। लेकिन उसे मांगने के लिए प्रेरित करता है, ताकि वह अल्लाह से अपनी नज़दीकी महसूस करे। मुजीब अपने दोस्तों और वलियों से बुराई को दूर करता है, अपने प्रियजनों से बला को उठाता है। उसकी क़बूलियत के कारण बड़ी-बड़ी मुसीबतें और विशाल समस्याएं दूर हो जाती हैं, यहाँ तक कि नुकसान पहुँचाने का इंतजार करने वाला दुश्मन भी नष्ट हो जाता है। सभी सृष्टियों को उससे मांगने की ज़रूरत है; उसके बिना उनका जीवन जारी नहीं रह सकता। अल-मुजीब मांगने वाले की मांग पूरी करता है, दुआ करने वाले को क़बूल करता है और तकलीफ़ में पड़ा व्यक्ति पुकारे तो उसकी मदद करता है।","वसी — 'जिसने अपने विशाल ज्ञान से सब कुछ घेरा और अपनी व्यापक दया से सबको समेटा'। यानी उसके गुण, विशेषताएं और उनसे संबंधित सब कुछ इतना विशाल है कि कोई भी उसे योग्य प्रशंसा नहीं दे सकता। अल्लाह वैसा ही है जैसा उसने स्वयं की प्रशंसा की है। वह वह है जिसकी अज़मत, सल्तनत, संपदा, कृपा और उदारता विशाल है और जिसकी दया और करम महान है। यदि लोग गरीब हों, तो अल्लाह अपनी कृपा से उन्हें स्वावलंबी और समृद्ध बना देता है। अल्लाह वसी और अलीम है — भलाई में प्रचुर और कृपा-करम में महान। अल्लाह के वसी नाम की बरकत से ही उसने बंदों के लिए दीन में विशालता रखी और उन्हें ऐसी चीज़ों का आदेश नहीं दिया जो उनकी शक्ति से परे हो।","सब कुछ ज्ञान के साथ करने वाला। अल्लाह के 'अल-हकीम' नाम का उल्लेख क़ुरआन करीम में लगभग सौ बार हुआ है। जब अल्लाह के दो नाम एक साथ एक जगह आते हैं, तो यह विशेष अर्थ ग्रहण करता है। उदाहरण के लिए, 'अज़ीज़ुन-हकीम' का अर्थ है: अल्लाह शक्तिशाली है, लेकिन बुद्धिमान भी। यानी शक्तिशाली होने के साथ-साथ वह हकीम भी है। अल्लाह की शक्ति अत्याचार की ओर नहीं ले जाती, बल्कि हकीम नाम और ज्ञान की विशेषता से अल्लाह इस शक्ति का सही उपयोग करता है। यह महान नाम संकेत करता है कि अल्लाह के लिए संपूर्ण निर्णय और ज्ञान स्थापित है। उसका ज्ञान सृष्टि, आदेशों और शरीअत में संपूर्ण है — वह हर चीज़ को उचित स्थान पर रखता है। कोई भी अल्लाह के ज्ञान पर आपत्ति नहीं कर सकता। निर्णय में संपूर्णता केवल उसी की है; वह अपने बंदों के बीच जैसा चाहे फ़ैसला करता है; उसके निर्णय को पलटने या जांचने वाला कोई नहीं।","सभी के लिए भलाई चाहने वाला। अल्लाह अपने नेक बंदों के लिए भलाई चाहता है, उन्हें प्यार करता है, उन्हें अपने क़रीब करता है और उनसे राज़ी होता है। अल्लाह का 'अल-वदूद' गुण का अर्थ है 'प्रेम करने वाला, क़रीब करने वाला, सुनने वाला और क़बूल करने वाला'। यह नाम क़ुरआन करीम में दो जगह आया है: 'बेशक मेरा रब दयालु और प्रेमपूर्ण है' (हूद, 90)। 'और वह बहुत क्षमाशील, बहुत प्रेमपूर्ण है' (बुरूज, 14)। यदि कोई बंदा इस नाम के अर्थ को सच्चे अर्थों में जाने, तो इसका प्रभाव उसके विश्वास, सोच, आचरण और जीवन के हर पहलू में प्रकट होगा। यह महसूस करते हुए कि अल्लाह वदूद है, यानी सबके लिए भलाई चाहता है, वह खुशहाल जीवन जीएगा और अल्लाह की सभी सृष्टियों से प्रेम विकसित होगा। वह चाहेगा कि अविश्वासियों को हिदायत मिले और पापी तौबा करें। इस प्रकार, इंसान के लिए जो कुछ भी वश में किया गया है, वह अल्लाह के अल-वदूद गुण से भलाई चाहने के कारण ही है।","जिसकी शान और क़द्र असीम रूप से उच्च है। 'अल-माजिद' और 'अल-मजीद' शब्दों का अर्थ है 'शान, श्रेष्ठता, ऊँचाई और पूर्णता की परम सीमा'। जब 'अल-मजीद' नाम अल्लाह के लिए प्रयोग किया जाता है, तो पूर्णता और उत्कृष्टता की सर्वोच्च डिग्री समझी जाती है। इंसान पूर्णता से प्यार करता है, इसलिए इंसान का नफ्स केवल अल्लाह की पहचान से भरता है। अगर वह अल्लाह के अलावा किसी और को चुने, तो कष्ट में रहता है और चैन नहीं पाता। इंसान की जिंदगी कई हालातों से गुज़रती है। मसलन, माल-दौलत जमा करके और इच्छित भौतिक चीज़ें हासिल करने के बाद, उनकी क़ीमत नज़रों में गिर जाती है और वे तुच्छ हो जाती हैं। लेकिन अगर अल्लाह को ढूंढे — चाहे कितनी भी मेहनत लगे — खुशहाल रहता है। क्योंकि अल्लाह के अंत तक पहुँचना असंभव है — वह अनंत है और उसकी पूर्णता पूर्ण है। जो अल्लाह के अल-मजीद गुण से अपने आचरण को सँवारे, उसे हर हाल में उदार होना चाहिए; मोमिन का कंजूस होना कदापि संभव नहीं।","लोगों के पास पैगंबर भेजने वाला। लोगों को हिम्मत भेजने वाला। मुर्दों को दोबारा जिंदा करने वाला। मसलन, अगर इंसान थोड़ा सा भी अल्लाह की ओर बढ़े, तो अल्लाह उस हरकत में बरकत देता है, हिम्मत बढ़ाता है, दिल खोलता है और इताअत में मदद करता है। अगर इंसान बातिल रास्ता, शहवत का रास्ता, भौतिक रास्ता या तकलीफ देने वाला रास्ता चुने, तो अल्लाह इस फैसले से दूर होने में कैसे मदद करता है? अल्लाह उसका सीना तंग कर देता है, जैसे वह आसमान पर चढ़ रहा हो। 'जिसे अल्लाह हिदायत देना चाहे, उसका सीना इस्लाम के लिए खोल देता है। और जिसे गुमराह करना चाहे, उसका सीना तंग और भींचा हुआ कर देता है, जैसे वह आसमान पर चढ़ रहा हो' (अनआम, 125)। अगर तुम सही फ़ैसला करो, तो अल्लाह तुम्हारा दिल खोलकर तुम्हारे फ़ैसले को पूरा करने में मदद करता है। अगर ग़लत फ़ैसला करो, तो अल्लाह तुम्हारा दिल तंग कर देता है। इसका उद्देश्य बुरा फ़ैसला करने से रोकना है। यह साबित हुआ कि अल-बाइस 'मार्गदर्शक और भेजने वाला' है। जब बंदे असमर्थ हो जाते हैं तो अल्लाह मदद और सहायता भी भेजता है।","हर चीज़ में मौजूद और हर चीज़ का गवाह। सब पर गवाही देने वाला। 'अश-शहीद' का अर्थ है 'अल्लाह अपनी सृष्टियों की निगरानी करता है, चाहे वे कहीं भी हों'। अल्लाह अपनी सृष्टियों के गले की नस से भी ज़्यादा क़रीब है। अल्लाह अपनी सृष्टियों को पूरी तरह घेरकर गवाह है। वह पूर्णता ज्ञान, दृष्टि, बुद्धिमान प्रबंधन और शक्ति के माध्यम से प्रकट होती है। यदि तुम हिलते हो, वह देखता है। यदि तुम बोलते हो, वह सुनता है। यदि तुम अपने दिल में कुछ छिपाते हो, वह जानता है। यदि तुम हिलते हो, वह देखता है। अश-शहीद का यह अर्थ भी है कि 'अल्लाह ने स्वयं और न्याय को गवाह बनाया'। 'अल्लाह ने न्याय स्थापित करते हुए गवाही दी कि उसके सिवा कोई पूज्य नहीं' (आल इमरान, 18)। इस प्रकार, यदि अल्लाह ने खुद के अलावा किसी ईश्वर के न होने की गवाही दी है, तो वह उन लोगों से दूर हो जाएगा जो अन्य प्राणियों पर निर्भर करते हैं और उन्हें अदब सिखाने के उद्देश्य से दंडित करेगा।","अपरिवर्तनीय, स्थिर सत्ता। सत्य को प्रकट करने वाला। अल्लाह हक़ है, उसका कलाम हक़ है, उसका वादा हक़ है, उसकी चेतावनी (जहन्नम का डर) हक़ है। अल्लाह की ज़ात, सिफ़त और अफ़आल में कोई शक नहीं — सब हक़ीक़त है। यह हक़ीक़त हमारे आसपास की चीज़ों में अमल में आती है। मसलन, सूरज का सुबह उगना, रात का दिन के बाद आना, ज़मीन का बारिश से रोज़ी पाना, उसकी लुत्फ़ व करम से सृष्टि पर उपकार, अपने मित्रों पर विशेष दया, सब्र करने वालों, परहेज़गारों और नेकोकारों के साथ होना, मज़लूमों की थोड़ी देर बाद भी मदद करना, टूटे हुओं को दुरुस्त करना और मजबूरों से नुकसान उठाना — यह सब बिल्कुल हक़ और सच है। 'हक़' का पहला अर्थ 'होना' है। इसकी विपरीत 'बातिल' का पहला अर्थ 'न होना' है। यदि वादा पूरा न हो, तो उसका वादा बातिल है। शैतान का वादा बिल्कुल बातिल है। अल्लाह का वादा बिल्कुल हक़ीक़त है।","सब के मामले जिसे सौंपे गए हैं। अल-वकील का अर्थ है 'बंदों की रोज़ी और मामलों में वकील'। इस प्रकार, बंदों का हर मामला अल्लाह को सौंपा गया है, सभी मामले उसी की ओर लौटते हैं। मसलन, जीवन भर इंसान को कई समस्याओं, खतरों और बीमारियों का सामना करना पड़ता है। ऐसा क्यों? इसकी हिकमत यह है कि बंदा अल्लाह को अपना वकील बनाए, उसकी ओर झुके, केवल उसी पर निर्भर रहे, उसका दरवाज़ा खटखटाए और उसका मुहताज बंदा बने। अल्लाह को वकील बनाने पर ही इंसान सच्चा तवक्कुल हासिल करता है। जो अल्लाह पर तवक्कुल करने का मज़ा चखे, वह सच्ची सुरक्षा, सुकून और शांति पाता है। अल्लाह ने इंसान को कमज़ोर बनाया। यदि मज़बूत बनाता तो वह अल्लाह पर तवक्कुल नहीं करता, उससे दुआ नहीं मांगता और फ़रमाँबरदारी नहीं करता। इस प्रकार, इंसान की कमज़ोरी केवल उसी के फ़ायदे में है। वह अपने सारे काम सबसे शक्तिशाली को सौंपकर उसी पर भरोसा करता है और उसे वकील बनाता है।","अत्यंत शक्तिशाली और बलवान सत्ता। अल-क़वी सम्पूर्ण शक्ति का स्वामी है। वह हर चीज़ पर सक्षम है, किसी भी स्थिति में उस पर कमज़ोरी हावी नहीं होती। वह इतनी शक्ति का मालिक है कि उसकी अज़मत के सामने सारी शक्ति नष्ट हो जाती है। अल-क़वी विजयी है, पराजित नहीं होता; उसी से पनाह मांगी जाती है, उसी की ओर झुका जाता है। यदि तुम इतने शक्तिशाली मालिक के साथ हो, क्या तुम्हें किसी से डरने का हक़ है? जब तक तुम अल्लाह के साथ हो, कौन तुम पर ग़ालिब हो सकता है? यदि अल्लाह तुम्हारे विरुद्ध है, तुम्हारे साथ कौन खड़ा हो सकता है? ऐ रब! जिसने तुझे पा लिया उसने क्या खोया? जिसने तुझे खो दिया उसने क्या पाया?! 'उन्होंने अल्लाह की सच्ची क़द्र नहीं की। बेशक अल्लाह शक्तिशाली और प्रतापी है' (हज, 74)।","अपनी शक्ति में दृढ़ और अटल सत्ता। कभी-कभी अचानक शक्ति आती है — ऐसी शक्ति क्षणिक होती है। लेकिन दृढ़, मज़बूत और शाश्वत शक्ति को अल-मतीन कहा जाता है। जब हम अल-मतीन शब्द को अल्लाह के लिए इस्तेमाल करते हैं, तो हम इसे संपूर्ण शक्ति और सामर्थ्य के अर्थ में इस्तेमाल करते हैं। अल्लाह की शक्ति प्रभाव डालती है, प्रभावित नहीं होती। संपूर्ण शक्ति का अर्थ है कि उसकी क़ुदरत सर्वोच्च स्तर पर है — धरती और आकाश में कोई भी चीज़ उसे कमज़ोर नहीं कर सकती। उसकी शक्ति किसी भी जगह और किसी भी समय स्थायी है। ऐ इंसान, यदि तुम अल-मतीन गुण वाले अल्लाह के साथ हो, तुम शक्ति महसूस करोगे और कोई भी तुम्हें नुकसान नहीं पहुँचा सकता। तुम्हें एहसास होगा कि तुम अल्लाह की हिफ़ाज़त, देखभाल और सुरक्षा में हो।","प्रेम करने वाला, सहायता देने वाला और अपनी प्रजा के कार्य चलाने वाला। अरबी में 'वली' दुश्मन की विपरीत है। जब यह नाम अल्लाह के लिए प्रयुक्त होता है, तो इसका अर्थ है 'पूरे जगत और सृष्टि के कार्य चलाने वाला, दोस्तों की मदद करने वाला, एहसान और कृपा से प्रेरित करने वाला और प्रेम करने वाला'। अल्लाह का बंदों का वली होना उनसे गले की नस से भी क़रीब होना है। सामान्य विलायत का अर्थ है देखभाल, प्रबंधन और मामलों का संचालन। विशेष विलायत का अर्थ है मोमिनों का दोस्त बनना, उनके क़रीब होना — यानी रक्षा करना, प्रेम करना और विजय देना। अल्लाह ने इस बारे में कहा: 'सुन लो, अल्लाह के वलियों पर कोई डर नहीं और वे ग़म में नहीं पड़ेंगे' (यूनुस, 63)।","सभी प्रशंसाओं से प्रशंसित। 'अल-हमीद' शब्द क़ुरआन करीम में 17 जगह आया है। 'अल-हम्द' शब्द 40 से अधिक जगहों पर आया है। सभी प्रशंसाएं अल्लाह के लिए हैं। वह अपने सभी गुणों, कार्यों और तक़दीर में प्रशंसनीय है। हम्द सबसे महान और व्यापक प्रशंसा है। हम्द दो प्रकार की होती है: 1. अल्लाह की दी हुई नेमतों पर हम्द करना — यानी अल्लाह के बंदों के प्रति की गई भलाई पर उसका शुक्र अदा करना। 2. वह हम्द जो अल्लाह ने स्वयं अपनी ओर नसब की। इमाम ग़ज़्ज़ाली ने कहा: 'अल-हमीद का अर्थ है 'प्रशंसित'। अल्लाह ने सृष्टि बनाने से पहले अज़ल में हम्द को अपनी ओर नसब किया। सृष्टि बनाने के बाद उसकी सृष्टि ने उसकी हम्द की।' अल्लाह की प्रशंसा हो, क्योंकि उसने रोज़ी, अक्ल, माल, परिवार, सेहत, अमान और इस्लाम की नेमत दी। जो अपने रब को अल-हमीद गुण से पहचाने, वह अपने रब की हम्द और सना से संतुष्ट होगा, लोगों की तारीफ का मुहताज नहीं होगा।","हर चीज़ का हिसाब रखने वाला। अल-मुहसी सब कुछ विस्तार से घेरे हुए है, ज़मीन पर और आसमान पर कोई भी चीज़ उससे छिपी नहीं। अल-मुहसी बाहरी सांसों और भीतरी भावनाओं का हिसाब रखता है। अल-मुहसी तुम्हारी इबादतों की गिनती सुरक्षित रखता है और तुम्हारी हर हालत से वाकिफ है। अल्लाह तुम्हारे अमलों का हिसाब करता है और तुम्हें मुलाकात के दिन के लिए तैयार करता है। मसलन, यह गिनना मुमकिन नहीं कि इंसान कितने दिन जिया, कितने समय टहला, कितने शब्द बोले। लेकिन अल्लाह तुम्हारे हर अमल का सूक्ष्म पहलू, विवरण, संदर्भ, प्रेरक कारण और उद्देश्य जानता है। क़यामत के दिन तुम जो कुछ देखोगे वह वही होगा जो अल्लाह ने गिन कर रखा है। अल-मुहसी वह है जो कामों के सूक्ष्म पहलुओं का हिसाब रखता है, रहस्यों को जानता है, प्रकट को देखता है और छिपे हुए से वाकिफ़ है। यदि इंसान यह विश्वास करे कि अल्लाह उसकी हर हरकत, हर सांस, हर अमल, दिल में छिपी हर नीयत और उद्देश्य का हिसाब रख रहा है — तो अल्लाह के साथ उसका रिश्ता बेहतर होगा।","सभी चीज़ों को शुरू से ही अस्तित्व में लाने वाला। अल-मुब्दी' का अर्थ है 'किसी पूर्व उदाहरण का संदर्भ लिए बिना, कुछ नहीं से चीज़ें बनाने वाला'। लेकिन जब कोई इंसान कुछ ईजाद करता है, तो वह निश्चित रूप से उस चीज़ के मूल से नकल करता है। उदाहरण के लिए, पानी के नीचे मछलियों को देखकर गोताखोरी का आविष्कार किया गया। इंजीनियर भी इमारत बनाने से पहले अपने दिमाग में तीन-चार प्रकार के मॉडल घुमाता है। लेकिन अल्लाह ने ब्रह्मांड बनाते समय किसी भी मॉडल का संदर्भ नहीं लिया और न होने से होने को बनाया। कुछ आरिफों ने कहा: 'अल-मुब्दी' ने अपने बंदे के दिल में नूर भेजा और उस नूर की वजह से उसका दिल रोशन हो गया।' क्योंकि नूर मिलने से पहले वह इंसान आलसी, निष्क्रिय और अज्ञात था। जब अल्लाह ने उसके दिल में शून्य से नूर डाला — वह एक अज्ञात व्यक्ति से सम्मानित व्यक्तित्व में बदल गया।","जो मिट गया उसे फिर से वापस अस्तित्व में लाने वाला। अल-मुईद सृष्टि को जीवन से मृत्यु की ओर वापस लाता है। मृत्यु हर जीवित प्राणी का अंत है। फिर मृत्यु के बाद सच्ची ज़िंदगी आती है। इस प्रकार, दुनियावी मृत्यु आख़िरत की सच्ची ज़िंदगी की शुरुआत है। अल-मुईद का अर्थ 'हिसाब के लिए सृष्टि को दोबारा जीवित करना' भी है। क्योंकि पुनरुत्थान में सवाल-जवाब, हिसाब-किताब और अमलों का प्रदर्शन होगा। वापस करने वाला हर मख़लूक़ से उसके अमल, बोल और दी गई नेमतों के बारे में सवाल करेगा। इंसान का जिस्म महीन कणों में टूट जाता है और फ़ना की ओर जाता है। वही कण फिर जमा होते हैं और इंसान को दोबारा बनाया जाता है। अगर किसी को भारतीय रीति से जलाकर उसकी राख आकाश या समुद्र में बिखेर दी जाए, तब भी अल्लाह उसे दोबारा जीवित करेगा। «कह दो: उन्हें वही जीवित करेगा जिसने उन्हें पहली बार पैदा किया, और वह हर सृष्टि को जानने वाला है» (यासीन, 79)। मोमिन का इस अल-मुईद गुण के प्रति अदब यह है कि वह अल्लाह की ओर अपनी वापसी को याद रखे और अल-मुईद नाम को बहुत दोहराए।","जीवित करने वाला। वह मुर्दों को जीवित करने वाला है। यह नाम सृष्टि को दोबारा जीवित करने से पहले भी उसके लिए उचित है। जैसे अल्लाह को मुर्दों में रूह डालकर जीवित करने के बाद जीवित करने वाला कहा जाता है, वैसे ही उन्हें बनाने से पहले और जीवन देने से पहले भी जीवित करने वाला कहा जाता है। ठीक जैसे वह सृष्टि बनाने से पहले खालिक (सृष्टिकर्ता) है। अल्लाह क़यामत के दिन मुर्दों को जीवित करेगा, इसलिए जीवित करने वाला नाम दिया गया। पस, जीवित करने का गुण अल्लाह में सृष्टियों को जीवित करने से पहले भी स्थापित है। अल्लाह सृष्टि को दो बार बनाता है। 'ऐ हमारे रब, तूने हमें दो बार मारा और दो बार जीवित किया' (ग़ाफिर, 11)। इस प्रकार, पहली बार न होने से होकर जीवित करता है। दूसरी बार मृत्यु के बाद जीवित करता है। एक तीसरा भी जीवित करना है — अल्लाह मृत दिल को जीवित करता है। जब मोमिन क़ुरआन पढ़ता है, उसकी आंखों से आंसू बहते हैं, शरीर कांपता है, दिल जोशीला होता है, अपने रब और उसकी इताअत से प्रेम करता है, हक़ को सुनता और हक़ बोलता है, अल्लाह का ज़िक्र करता है, अल्लाह की रज़ा के लिए कोशिश करता है — और इन चीज़ों से उसका दिल जीवित रहता है।","मारने वाला। सभी जीवों की जान लेने वाला। 'और वही मुझे मारेगा, फिर मुझे जीवित करेगा' (शुअरा, 81)। कोई भी व्यक्ति किसी अन्य को मार नहीं सकता या किसी मृत को जीवित नहीं कर सकता। यदि कोई कहे 'मैं फांसी के माध्यम से मारता हूं', तो हम उसे कहते हैं: 'मृत्यु फांसी के बिना भी होती है — मृत्यु शरीर की संरचना को नुकसान पहुंचाए बिना होती है। लेकिन तुम जो फांसी करते हो वह शरीर को नुकसान पहुंचाती है।' हमें दृढ़ता से विश्वास करना चाहिए कि अस्तित्व में अल्लाह के अलावा कोई भी जीवन को समाप्त करने की हिम्मत नहीं कर सकता। इंसान केवल उसकी तक़दीर के अनुसार मरता है। यदि अल्लाह मारने वाला है, तो इस आयत का क्या अर्थ होगा: 'तुम्हारे लिए नियुक्त किया गया मृत्यु का फ़रिश्ता तुम्हारी जान लेगा। फिर तुम अपने रब की ओर लौटाए जाओगे' (सज्दा, 11)? कुछ उलमा ने जवाब दिया: 'वास्तव में अल्लाह ने मृत्यु बनाई। मृत्यु की क्रिया भी अल्लाह की ओर से है। लेकिन कारणों की दुनिया में मृत्यु को मृत्यु के फ़रिश्ते को सौंपा गया है। मृत्यु को अंजाम देने वाला वास्तव में केवल अल्लाह अकेला है।' अल-मुमीत का अर्थ यह भी है: अपने प्रिय लोगों पर दया करके कठोर क्रोध वाले ज़ालिमों को मारने वाला, और वर्षा न बरसाकर उपजाऊ ज़मीनों को मृत कर देने वाला।","जीवित। वह हमेशा जीवित है, वह मरता नहीं। यानी अल्लाह की ज़िंदगी अबदी है, मृत्यु से समाप्त नहीं होती। साथ ही, अल्लाह की ज़िंदगी अज़ली है, पहले ग़ैर-मौजूद नहीं थी। एकमात्र अल्लाह की ज़िंदगी केवल उसी को विशेष जीवन है, बंदों की तरह किसी और स्रोत से नहीं दी गई। यह जीवन अज़ली और अबदी है — न आरंभ है न अंत। अल्लाह की ज़िंदगी किसी भी पहलू से बंदों की ज़िंदगी जैसी नहीं है। अल्लाह का अल-हय्य गुण हमेशा बाक़ी रहने वाला और सदा जीवित का अर्थ देता है। जब हम 'अल्लाह जीवित है' कहते हैं, तो समझते हैं वह सदा जीवित है। जब 'फ़लां जीवित है' कहते हैं, तो समझते हैं वह अस्थायी रूप से जीवित है। अल्लाह का हय्य गुण उसकी अपनी ज़ात में अबदी ज़िंदगी है। उस जैसा कुछ नहीं। लेकिन मख़लूक़ की ज़िंदगी उसकी ज़ात में नहीं बल्कि अल्लाह की मदद पर निर्भर है। अगर अल्लाह मदद काट दे, मख़लूक़ बेजान लाश बन जाती है। मख़लूक़ लगभग एक हज़ार कारणों से जीवित रहती है। यदि अल्लाह उनमें से किसी एक को भी न चलाए, उदाहरण के लिए दिल को रोक दे, तो उसकी ज़िंदगी समाप्त हो जाती है।","स्वयं क़ाइम और दूसरों को क़ाइम रखने वाला। अल्लाह का 'अल-क़य्यूम' गुण का अर्थ है कि अल्लाह तबारक व ताला हर चीज़ पर खड़ा है और हर खड़ी चीज़ केवल उसी की वजह से खड़ी है। इस प्रकार, अल्लाह का क़ाइम होना किसी और जैसा नहीं — यह स्थायी है। अल-क़य्यूम को प्रबंधक कहा जाता है। अल्लाह ख़ुद को और अपनी सृष्टि को भी प्रबंधित करता है। हम सभी अल्लाह के प्रबंधन में हैं। अल्लाह हमें ज़िंदगी देता है और हमारा प्रबंधन करता है। जिगर इतना रहस्यमय अंग है कि उस पर पाँच हज़ार कार्य सौंपे गए हैं। यदि अल्लाह उसे सहारा देना बंद कर दे, तो वह बाज़ारों में बिकने वाले जानवर के जिगर जैसा एक ऊतक बन जाएगा। आँखें, कान, जीभ, दिल, फेफड़े — ये सब अल्लाह के प्रबंधन में काम करते हैं। यदि अल्लाह समर्थन बंद कर दे, तो ये जानवरों की आँखों और कानों की तरह कचरे में फेंक दिए जाएंगे।","खोजने वाला। जो चाहे उसे पाने वाला। इस काम में कोई उसे नहीं रोक सकता। कभी-कभी इंसान कमज़ोरी की वजह से कहता है: 'मैंने फ़लां चीज़ ढूंढी लेकिन नहीं मिली।' लेकिन अल्लाह अल-वाजिद गुण से सब कुछ पाने वाला है, उससे कोई चीज़ बचती नहीं। वह जो मांगे और चाहे वह सब पाता है। जब इंसान को किसी गुण से विशेषित किया जाए, तो वह सापेक्ष है। लेकिन जब अल्लाह को किसी गुण से विशेषित किया जाए, तो वह पूर्ण (mutlaq) है। अस्तित्व अनस्तित्व का विरोध है। हमारे रब 'वाजिबुल वुजूद' हैं, यानी अज़ली और अबदी हैं। अल्लाह के अलावा बाकी 'मुम्किनुल वुजूद' हैं, यानी पहले न-होना था और फिर न-होने से ख़त्म होता है। अल्लाह अल-क़दीम और अल-बाक़ी है — उससे पहले और उसके बाद कुछ नहीं था। अल-वाजिद का अर्थ 'कभी मुहताज न होने वाला, बेनियाज़' भी है।","महानता और सम्मान के स्वामी। हमने पहले अल्लाह के 'अल-मजीद' गुण को 'शान और क़द्र में असीम रूप से उच्च' के रूप में सीखा। 'अल-मजीद' शब्द अतिशयोक्ति के लिए प्रयुक्त होता है — यानी असीम रूप से महान और अत्यंत सम्माननीय। 'अल-माजिद' गुण क़ुरआन करीम में नहीं बल्कि हदीस में आया है। जबकि 'अल-मजीद' गुण क़ुरआन में उल्लिखित है। 'अल-माजिद' शब्द शान, श्रेष्ठता, ऊँचाई और पूर्णता का अर्थ देता है। अल-माजिद का अर्थ 'करम में विशाल और बेनियाज़' भी है। इस प्रकार, यह जानते हुए कि अल्लाह वह है जिसकी उदारता विशाल है, जो बेनियाज़ है, जिसकी शान और क़द्र उच्च है और जो चीज़ें देता है, तुम्हें भी इस गुण से सुसज्जित होना चाहिए और इसमें अपना हिस्सा पाने के लिए लोगों को माफ करने वाला, उनसे नरम, उन्हें क्षमा करने वाला और अपना माल ग़रीबों पर खर्च करने वाला बनना चाहिए।","एकमात्र, एक। वह अपनी ज़ात, सिफ़ात और कार्यों में एकमात्र है। 'तौहीद' शब्द इसी 'अल-वाहिद' शब्द से लिया गया है। हर मोमिन जानता है कि बंदे के सीखने योग्य सबसे उत्तम चीज़ तौहीद है। तौहीद ज्ञान की परम सीमा है। सभी नबियों के आह्वान की विषयवस्तु और मूल बिल्कुल तौहीद है। तौहीद ही दीन है। यदि तुम अपने में बेचैनी और कष्ट देखो, तो इसका अर्थ है तुम्हारी तौहीद की समझ कमज़ोर हो गई है। क्योंकि ऐसी उदासी इस सोच से उत्पन्न होती है कि तुम्हारा भविष्य और रोज़ी तुम जैसे इंसानों के हाथों में है। यदि तुम जानते हो कि तुम एकमात्र अल्लाह — सबसे अधिक दयावान में से सबसे दयावान — की हिफ़ाज़त में हो, तो तुम सुकून और शांति की ओर क़दम उठाओगे। तौहीद यह कहना है कि तुम्हारे मन में आने वाली हर चीज़ के विपरीत अल्लाह है। तौहीद का अर्थ है कि अल्लाह अपनी ज़ात, सिफ़ात और कार्यों में एकमात्र है। कुछ आरिफ़ों ने कहा: 'अल-वाहिद तुम्हें सबकी तरफ़ से काफ़ी है, सब मिलकर तुम्हें अल-वाहिद की तरफ़ से काफ़ी नहीं हो सकते।' वाहिद और अहद में अंतर: 'अल-वाहिद' — कोई शरीक नहीं। 'अल-अहद' — कोई समान नहीं। तौहीद दो प्रकार की है: 1. रुबूबिय्यत की तौहीद — अल्लाह अपने राज्य में एक है: वह सृष्टिकर्ता, रोज़ी देने वाला, प्रदान करने वाला, रोकने वाला, ऊँचा करने वाला, नीचा करने वाला। 2. उलूहिय्यत की तौहीद — केवल उसी की इबादत करना, किसी और की न करना और किसी को उसका शरीक न ठहराना।","एकमात्र, जिसका कोई सदृश नहीं। अल-अहद और अल-वाहिद के बीच अंतर यह है कि अल-वाहिद का अर्थ है कोई शरीक न होना, जबकि अल-अहद का अर्थ है कोई समान या सदृश न होना। अल्लाह ने सूरह इख़लास में अपने बारे में कहा: 'कहो: वह अल्लाह एक है। अल्लाह समद है (किसी का मुहताज नहीं, सब उसके मुहताज हैं)। न उसने जन्म दिया, न वह जन्मा। और उसके समान कोई नहीं' (इख़लास, 1-4)। इस प्रकार, अल-अहद का अर्थ है कि वह अपनी ज़ात, गुणों और कार्यों में एकमात्र है, और कोई भी चीज़ या कोई भी व्यक्ति उससे मिलता-जुलता नहीं, उसके बराबर नहीं आ सकता और उसका साथी नहीं बन सकता। यह नाम तौहीद की सबसे शुद्ध अभिव्यक्ति है — जो अल्लाह की ज़ात, गुणों और कार्यों में एकता को दर्शाता है। मुसलमान अपनी रोज़ाना की नमाज़ों में इस नाम को समाहित करने वाली सूरह इख़लास को बार-बार पढ़ते हैं, अपने ईमान को नवीनीकृत करते हुए। नबी (सल्लल्लाहु अलैहि वसल्लम) ने इस सूरह को 'क़ुरआन के एक-तिहाई के बराबर' बताया, क्योंकि यह अल्लाह की एकता के सबसे महत्वपूर्ण अक़ीदे को अपने में समेटती है। जो कोई सच्चे दिल से अल-अहद के अर्थ को समझे, उसके दिल में ऐसी शांति आती है जो किसी और चीज़ पर निर्भर नहीं करती, क्योंकि वह केवल एकमात्र सत्ता पर भरोसा करता है।","'अस-समद' गुण में कई अर्थ शामिल हैं: जिसकी इताअत की जाती है, महान सरदार, जिसके बिना कोई काम पूरा नहीं होता; किसी को उसकी ज़रूरत नहीं, बल्कि सबकी ज़रूरत उसी को है; जब सारी सृष्टि नष्ट हो जाए, तब भी वह हमेशा बाक़ी रहता है; 'पेट न होने' के अर्थ में भी आता है, क्योंकि अल्लाह खाने-पीने जैसी इंसान की चीज़ों से दूर है; कठिनाई के समय जिसका इरादा किया जाता है। अस-समद का मतलब है कि सृष्टि उसकी ओर मुड़ती है और हर काम में उसी का इरादा करती है, अपने दीनी और दुनियावी कामों को सुधारने के लिए उसी की ओर रुजू करती है, मुसीबतों और चिंताओं के समय उसके सामने सिर झुकाती है, दुख और ग़म के समय उसी से गिड़गिड़ाती है, और कठिनाई के समय मदद मांगने के लिए अल्लाह के अलावा कोई और नहीं है। जो बंदा अस-समद के अर्थ को अच्छी तरह समझ ले, वह अपने में शक्ति, प्रतिष्ठा और अल्लाह के अलावा किसी और पर निर्भर न रहना हासिल करता है। अस-समद सरदारी में पूर्ण सय्यिद, शरफ़ में पूर्ण शरीफ़, महानता में पूर्ण अज़ीम, सहनशीलता में पूर्ण हलीम, धन में पूर्ण ग़नी, शक्ति में पूर्ण जब्बार, ज्ञान में पूर्ण आलिम और हिक्मत में पूर्ण हकीम है।","असीम शक्ति का स्वामी। वह हर चीज़ पर सक्षम है। हर काम उसके लिए आसान है। अल्लाह अज़ल से हर चीज़ पर सक्षम है। यदि वह अज़ल से सक्षम न होता, तो कब और कैसे वह हर चीज़ पर सक्षम हो सकता? अल-क़दीर, अल-मुक़्तदिर भी अल-क़ादिर गुण जैसे हैं और अपनी विशेषता की श्रेष्ठता के कारण एक-दूसरे से भिन्न हैं। अल्लाह की क़ुदरत पूर्ण है — अपनी क़ुदरत से उसने न होने से अस्तित्व बनाया, अपनी क़ुदरत से उनके मामलों का प्रबंधन किया। अपनी क़ुदरत से वह जीवन और मृत्यु देता है और भलाई करने वालों को इनाम देता है, बुराई करने वालों को दंड देता है। यदि वह कुछ चाहे और कहे 'हो जा', तो वह अस्तित्व में आ जाता है। अपनी क़ुदरत से वह दिलों को जिधर चाहे मोड़ता है। यदि तुम अल्लाह के आदेशों की रक्षा करो और उसकी मनाही से बचो, तो अल्लाह भी तुम्हारी रक्षा करेगा। इस प्रकार, जो अल्लाह के अल-क़ादिर गुण को अच्छी तरह समझकर उससे सुसज्जित हो जाता है, वह हमेशा महसूस करता है कि वह अल्लाह के साथ है। वह अल्लाह के आदेशों का बिना विचलित हुए पालन करता है। यदि वह कुछ माँगे, तो केवल अल्लाह से ही माँगता है।","अत्यंत शक्तिशाली। अल-मुक़्तदिर गुण अल-क़दीर और अल-क़ादिर गुणों से भी अधिक बल देने वाला है। अल-मुक़्तदिर का अर्थ है कि अल्लाह उन सभी चीज़ों पर हावी है जिन्हें उसने शक्ति का हिस्सा दिया है। अल-मुक़्तदिर का अर्थ है कि वह न केवल कमज़ोरों पर बल्कि अत्यंत शक्तिशालियों पर भी हावी है। अल-मुक़्तदिर अपने ज्ञान से चीज़ों को नापता है और अपनी शक्ति से उन्हें अंजाम देता है। उसका ज्ञान और शक्ति पूर्ण है। अल-मुक़्तदिर गुण अल-क़दीर और अल-क़ादिर दोनों गुणों को एक साथ समेटता है। अल्लाह का अल-क़ादिर नाम का अर्थ है कि वह चीज़ों को अपने ज्ञान से नापता है। अल्लाह हर चीज़ को बनाने और सृजित करने से पहले तक़दीर करता है। अल्लाह का अल-क़दीर नाम पूर्व ज्ञान के अनुसार पूर्ण शक्ति से सृजन करना है। अतः अल-मुक़्तदिर नाम का अर्थ है पहले से तय दृढ़, पूर्ण, परिपूर्ण और सशक्त शक्ति-योजना का पूर्ण रूप से साकार होना। तो सच्चे मुसलमान की शक्ति कहाँ से आती है? यदि मुसलमान अल-मुक़्तदिर गुण वाले अल्लाह के साथ हो, तो वह उसकी मदद करेगा और उसे दुश्मन पर जीत प्रदान करेगा। मुसलमानों की समस्या का समाधान यही है कि वे बीच में कोई माध्यम बनाए बिना अल-मुक़्तदिर गुण वाले अल्लाह पर भरोसा करें।","आगे बढ़ाने वाला। वह जिसे चाहे और जो चाहे उसे जिसे चाहे और जो चाहे उससे आगे बढ़ाता है। यह नाम क़ुरआन में उल्लिखित नहीं है। यह इमाम बुखारी, मुस्लिम और इब्न ख़ुज़ैमा की रिवायत की गई हदीस में आया है। यदि हम अल्लाह को अल-मुक़द्दिम कहें, तो इसका अर्थ है कि वह अपनी इच्छा और हिकमत के अनुसार आगे बढ़ाता है। उदाहरण के लिए, वह कुछ को दूसरों से पहले मारता है। या अपनी हिकमत के अनुसार मुसीबत में डालते समय एक नबी को दूसरे से, एक सहाबी को दूसरे सहाबी से, एक मोमिन को दूसरे से आगे बढ़ाता है। 'हर उम्मत की एक अजल है। जब उनकी अजल आ जाए, तो वे एक घड़ी भी पीछे या आगे नहीं हो सकते' (आराफ, 34)। इस प्रकार, यदि तुम इस नाम के अर्थ को समझो और दृढ़ता से विश्वास करो कि तुम्हारी ज़िंदगी अल्लाह के हाथ में है और तुम्हारी ज़िंदगी की अवधि न आगे बढ़ाई जा सकती है न पीछे, तुम्हारी आत्मा प्रसन्न होगी, तुम बहादुर बनोगे और बिना किसी के सामने अपमानित हुए या सिर झुकाए इज़्ज़त और सम्मान के साथ जीओगे।","देर करने वाला। वह जिसे चाहे और जो चाहे उसे जिससे चाहे और जिससे चाहे देर करता है। अल-मुअख्खिर भाषा में अल-मुक़द्दिम का विपरीत है, जिसका अर्थ है पीछे धकेलना। बंदों के तौबा करने के लिए, वह उन्हें अपनी दया और हिकमत के अनुसार दंड देने में देरी करता है। अल्लाह इतना सहनशील है कि यदि इंसान गुनाह करे, तो वह उसे तौबा करने का मौक़ा देता है। जब उमर रज़ियल्लाहु अन्हु एक चोर को दंड देना चाहते थे, चोर ने कहा: 'अल्लाह की क़सम, यह मेरी पहली चोरी है।' तब उमर रज़ियल्लाहु अन्हु ने कहा: 'तुमने झूठ बोला, अल्लाह तुम्हारा पहला गुनाह ज़ाहिर नहीं करता। वह सहनशील होने के कारण ज़ाहिर करना देर करता है, तुमने इससे पहले भी चोरी की है।' वास्तव में, यदि इंसान कोई गुनाह करके उसमें पूरी तरह डूब जाए और तौबा न करे, और उस किए गए गुनाह पर गर्व करे, तो उसका अज़ाब जल्दी आता है। लेकिन यदि कोई गुनाह करे, तो अल्लाह मोहलत देता है। यदि वह गुनहगार अपने किए गए गुनाह पर पछताए, तो वह पछतावा भी तौबा है। अल्लाह केवल उसी को अज़ाब में पकड़ता है जो अपने गुनाह में पूरी तरह डूब जाए। इस प्रकार, अल्लाह अपनी पूर्ण हिकमत और पूर्ण दया के अनुसार नाफ़रमान बंदों पर आफ़त और मुसीबत उतारने में देर करता है। यदि बंदे तौबा करें, तो अल्लाह उनका दोस्त है। यदि वे तौबा न करें, तो अल्लाह उनका चिकित्सक है। 'यदि अल्लाह लोगों को उनके ज़ुल्म पर पकड़ता, तो धरती पर कोई जीव न छोड़ता। लेकिन वह उन्हें एक निश्चित अवधि तक मोहलत देता है' (नहल, 61)।","वह हर चीज़ से पहले था — यानी वह तब मौजूद था जब सारी सृष्टि मौजूद नहीं थी। सृष्टि को 'अव्वल' गुण वाले अल्लाह ने बनाया। यानी अल्लाह के अस्तित्व की कोई शुरुआत नहीं है। अल्लाह अव्वल है, क्योंकि उससे पहले वास्तविकता में कुछ नहीं था। वह अपनी ज़ात और शान में सब कुछ से पहले आने से महान है। उसे किसी भी चीज़ में किसी और की ज़रूरत नहीं। बल्कि हर चीज़ को हर काम में उसकी ज़रूरत है। इसलिए तुम हर चीज़ में अव्वल रहने वाले के साथ रहो, कमज़ोर मख़लूक़ के साथ नहीं, बल्कि शक्तिशालियों में सबसे शक्तिशाली के साथ रहो। अल-अव्वल का मतलब है कि बाकी सब कुछ उसी की ओर लौटता है, या वह परिणाम प्राप्त करने का मूल प्रारंभिक बिंदु है। यानी अल्लाह हर चीज़ का प्रथम कारण है। मसलन, मुर्गी अंडे से पैदा हुई। और अंडा मुर्गी से। इस श्रृंखला का कोई अंत नहीं। अंततः सवाल उठता है: पहली मुर्गी किसने बनाई? अव्वल गुण वाले अल्लाह ने मुर्गी बनाई। इस प्रकार, अल्लाह हर चीज़ का मुख्य कारण और प्रथम है।","जब सब कुछ नष्ट हो जाए, तब भी वह स्वयं बना रहता है। अल्लाह अल-आख़िर है। वह हमेशा मज़लूम के साथ है। कभी-कभी पति पत्नी पर ज़ुल्म करके मनमाने ढंग से तलाक़ दे देता है। अल्लाह इस नेक औरत का सम्मान करते हुए, उसे उसके पहले पति को भुला देता है और बदले के तौर पर उसे दूसरा नेक पति देता है। इस प्रकार, अंतिम फैसला अल्लाह खुद देता है। कभी-कभी बड़ा बेटा पिता की सारी संपत्ति अपने छोटे भाइयों को दिए बिना ले लेता है। अल्लाह अल-आख़िर गुण से छोटे भाइयों के मामलों में सफलता पर सफलता देता है, और बड़े भाई का काम बिगाड़ देता है। नतीजतन, बड़ा भाई अपने भाइयों के लिए काम करने पर मजबूर हो जाता है। इस प्रकार, अंतिम फैसला अल्लाह खुद देता है। अल्लाह ने इस बारे में कहा: 'क्या उन्होंने किसी काम का फैसला कर लिया? तो बेशक हम भी फैसला करने वाले हैं' (ज़ुख़रुफ़, 79)। जो इंसान अल्लाह को नहीं पहचानता, वह अल्लाह से नहीं डरता। हमारे नबी (सल्लल्लाहु अलैहि वसल्लम) जिन्होंने अल्लाह को सच में पहचाना, अपनी जगह पर खजूर देखकर खाने की बहुत इच्छा होने पर भी न खाकर कहा: 'ऐ आइशा! अगर यह सदक़े की खजूर न होती तो मैं ज़रूर खा लेता।' इस अल-आख़िर नाम से तुम्हें मिलने वाली मदद यह है कि तुम अल्लाह से जुड़ो और अपने आप को मज़बूत महसूस करो।","उसका अस्तित्व स्पष्ट और प्रकट है। वह हर चीज़ से प्रकट-श्रेष्ठ है। यदि हम अल्लाह को अज़-ज़ाहिर कहें, तो हम समझते हैं कि वह अपनी श्रेष्ठता, विजय और शान की ऊँचाई में सबसे ऊपर है। वह पूर्णता के हर अर्थ में विजयी है। उसका ज्ञान हर चीज़ को प्रकट और छिपे दोनों रूप में समेटता है। वह इतना प्रकट है कि उसके गुण तार्किक प्रमाण से जाने जाते हैं। यूनुस अलैहिस्सलाम मछली के पेट के अंधेरे में, समुद्र के अंधेरे में और रात के अंधेरे में अकेले रह गए, तो अल्लाह ने अज़-ज़ाहिर गुण से उन्हें सुरक्षा में निकाला। अल्लाह अज़-ज़ाहिर गुण से सभी छिपी चीज़ों को प्रकट करने वाला भी है। जब किसी ने अली रज़ियल्लाहु अन्हु से पूछा: 'अल्लाह कब हुआ?', तो अली रज़ियल्लाहु अन्हु ने जवाब दिया: 'वह कभी नहीं हुआ कि तुम ऐसा सवाल पूछ रहे हो। वह हमेशा प्रकट है, यानी दिखाई देता है।' किसी ने दिलों के चिकित्सक मुर्शिद से पूछा: 'क्या आप अल्लाह के लिए तड़पते नहीं?' उसने कहा: 'अल्लाह की क़सम, नहीं।' उस व्यक्ति ने कहा: 'कैसे?' मुर्शिद ने जवाब दिया: 'अल्लाह कब नज़रों से ग़ायब हुआ कि मैं उसके लिए तड़पूं, आख़िर वह हमेशा प्रकट है?!'","वह आँखों से नहीं दिखता। वह सबसे ज़्यादा छिपी-गुप्त चीज़ों को जानता है। जो नज़र से रोका गया हो उसे बातिन कहा जाता है। अल्लाह को अल-बातिन कहने का मतलब है कि वह दृश्य धारणा से रोका गया है। 'आँखें उसे नहीं पकड़ सकतीं, वह आँखों को पकड़ता है' (अनआम, 103)। इसलिए, इस दुनिया में अल्लाह को आँखों से नहीं देखा जा सकता। जो कोई अल्लाह को देखने का दावा करे, उसका दावा झूठा है। लेकिन उसे आख़िरत में देखा जाएगा। 'उस दिन (मोमिनों के) चेहरे चमकते हुए अपने रब को देखते होंगे!' (क़ियामह, 22-23)। क्योंकि इंसान की देखने की क्षमता और विशेषता इस दुनिया में अल्लाह को देखने के लिए उपयुक्त नहीं है। लेकिन जन्नत में इंसान की प्रकृति इस दुनिया की प्रकृति से अलग है। जन्नत में अल्लाह को देखने की संभावना है। अल्लाह अपने बंदों की परीक्षा और आज़माइश के लिए आँखों से छिपा रहता है। इसलिए, अल्लाह ने मोमिनों को 'बिना आँखों से देखे ग़ैब पर ईमान लाने वाले' कहा है। अदृश्य अल-बातिन को जानने और सच्चा ज्ञान प्राप्त करने के लिए बुद्धि सबसे अच्छा साधन है। यद्यपि अल्लाह को आँखों से देखने की कोई संभावना नहीं है, फिर भी ब्रह्मांड की हर चीज़ उसके अस्तित्व की ओर इशारा करती है। इसे समझने का सर्वोच्च साधन, जैसा कि हमने ऊपर कहा, बुद्धि है। दुनिया की हर चीज़ अल्लाह के एक होने की गवाही देती है।","हर चीज़ का संरक्षक, स्वामी। अल-वली, अल-मौला और अल-वाली शब्द एक ही मूल से लिए गए हैं और इसका अर्थ है 'अपनी सृष्टि के मामलों का प्रबंधन करने वाला'। इस प्रकार, अल-वाली का अर्थ है 'मामलों का पूर्ण प्रबंधक और नियंत्रक, और ब्रह्मांड का पालनकर्ता'। इसे पूरा करने के लिए, उसे सर्वज्ञ, सर्वशक्तिमान और सर्वज्ञात गुणों का भी स्वामी होना चाहिए। अल्लाह वह है जो इन सभी गुणों का स्वामी है। अल-वाली गुण का स्वामी होने के लिए कौशल की आवश्यकता है, क्योंकि ज्ञान एक चीज़ है और कौशल दूसरी। इस प्रकार, इंसान का कौशल 'घटना' है (यानी नया उत्पन्न हुआ), जबकि अल्लाह का कौशल 'अज़ली' है (शुरू से मौजूद)। इंसान कभी-कभी कुछ पूरा करना चाहता है लेकिन उसमें सक्षम नहीं होता। अल्लाह, इसके विपरीत, 'जो चाहे वह करने वाला है' (बुरूज, 16)। लेकिन जो मोमिन अल-वाली पर निर्भर करता है — सभी मामलों का पर्यवेक्षक, ज़मानतदार, कुशल, जो चाहे वह पूरा करने वाला — वह किसी भी कठिनाई में शांत जीवन जीता है। इमाम अबू हनीफ़ा, जिन्होंने अल्लाह के अल-वाली गुण को पूरी तरह समझा, हदीस 'जो इल्म तलब करे, अल्लाह उसकी रोज़ी की ज़मानत लेता है' पढ़कर, इल्म के क्षेत्र में सबसे ऊँची चोटियां फतह कीं। अल्लाह के अल-वाली गुण को पूरी तरह समझने वाले महान ताबिईन में से हसन बसरी के पास बसरा के वाली यज़ीद की ओर से एक आदेश आया। तब हसन ने कहा: 'अल्लाह तुम्हें यज़ीद से बचा सकता है, लेकिन यज़ीद तुम्हें अल्लाह से नहीं बचा सकता', और उन्होंने वह काम नहीं किया।","कमियों से ऊपर की सत्ता। हर चीज़ उसकी अज़मत और हुकूमत के अधीन है। उसके सिवा कोई पूज्य नहीं। यानी कोई ऐसा नहीं जो उस पर विजय पा सके या उससे बहस कर सके। यह गुण क़ुरआन करीम में एक जगह आया है: 'वह गैब और हाज़िर दोनों को जानने वाला है। वह महान है, परम उच्च है' (राद, 9)। लेकिन कुछ लोग यह मानकर घबरा जाते हैं कि धरती पर कोई अत्यंत शक्तिशाली शक्ति मौजूद है। वास्तव में, आंख की पुतली में देखने की क्षमता देने वाली वह शक्तिशाली शक्ति अल्लाह के हाथ में है। यदि इंसान अल्लाह के अल-मुताअली गुण को पूरी तरह समझे, तो वह इज़्ज़त, सम्मान, ताक़त और साहस के साथ जीवन जीता है। इमाम तबरानी ने अबू दर्दा से यह रिवायत बयान की है। अल्लाह ने कहा: 'मैं बादशाहों का बादशाह और मालिक हूं। बादशाहों के दिल मेरे हाथ में हैं। यदि बंदे मेरी इताअत करें, तो मैं बादशाहों के दिलों को उनकी ओर मोड़ता हूं, उन्हें दयालु और कोमल बनाता हूं। यदि बंदे मेरी नाफ़रमानी करें, तो मैं बादशाहों के दिलों को उनके ख़िलाफ़ मोड़ता हूं, उन्हें क्रोधित और कठोर बनाता हूं, नतीजतन बादशाह उन्हें तरह-तरह की यातना देते हैं। तुम बादशाहों से मांगने में व्यस्त न रहो, बल्कि जगत के पालनहार के ज़िक्र और उसके सामने विनम्रता में व्यस्त रहो, तब मैं खुद उनके लिए काफी हो जाऊंगा।'","महान भलाई करने वाला, अतिशयोक्ति के रूप में भलाई को अंजाम देने वाला। यदि हम इस नाम को अल्लाह के लिए इस्तेमाल करें, तो हम पूर्ण भलाई समझते हैं। अल्लाह की पूर्ण अता, दुनिया और आख़िरत में उसकी भलाई, दिल को खुशी से भरना, इंसान को सेहतमंद और सुरक्षित करना, उसकी रोज़ी को प्रचुर बनाना है। अल-बर्र अल्लाह की भलाई है, अल-बिर्र वह है जो अल्लाह अता करता है। 'अल-बिर्र' शब्द के 'दुनिया और आख़िरत में भलाई' और 'तक़वा' के अर्थ भी हैं। दुनिया में भलाई है हिदायत, सेहत, विचार की शांति, सुकून, प्रचुर रोज़ी, नेक पत्नी, नेक संतान और हलाल पेशे। आख़िरत में भलाई है जन्नत से सम्मानित होना, वहां हमेशा रहना, हूरें, सेवक, नीचे से बहने वाली नहरों वाले बाग़, तरह-तरह के फल, अल्लाह के चेहरे को देखना और सबसे बड़ी बात, अल्लाह की रज़ा से सम्मानित होना। इस प्रकार, अल्लाह अल-बर्र गुण से अपने बंदों को दुनिया और आख़िरत में भलाई प्रदान करता है। इस अल-बर्र नाम में बंदे का हिस्सा हर तरह के अच्छे कामों में व्यस्त रहना है। अल्लाह ने अच्छे कामों को एक आयत में इकट्ठा किया है: 'नेकी यह नहीं है कि तुम अपने चेहरे पूर्व और पश्चिम की ओर फेरो, बल्कि नेक वह है जो अल्लाह पर, आख़िरत के दिन पर, फ़रिश्तों पर, किताबों पर और नबियों पर ईमान लाया, और अपना माल उससे प्रेम होने के बावजूद रिश्तेदारों, यतीमों, मिस्कीनों, मुसाफ़िरों, माँगने वालों को और गुलामों को आज़ाद कराने में देता है, नमाज़ क़ायम करता है और ज़कात देता है; और जो अपने वादे पूरे करते हैं जब वादा करें, और जो तंगी, बीमारी और जंग के समय सब्र करते हैं। यही लोग सच्चे हैं और यही लोग परहेज़गार हैं' (बक़रा, 177)।","बंदों को तौबा की ओर मार्गदर्शन करने वाला और उनकी तौबा को बहुत अधिक स्वीकार करने वाला। अत-तव्वाब अरबी व्याकरण में अतिशयोक्ति के लिए प्रयुक्त शब्द है। यदि इस शब्द को अल्लाह के लिए इस्तेमाल करें, तो हम मात्रा और प्रकार को समझते हैं। यानी समझा जाता है कि अल्लाह चाहे गुनाह की मात्रा कितनी भी हो या किसी भी प्रकार का हो, बहुत अधिक माफ करता है। 'तौबा' शब्द का शाब्दिक अर्थ है 'एक चीज़ से दूसरी चीज़ की ओर लौटना'। तौबा उस समय बचने का रास्ता है जब इंसान को गलतियां घेर लें। तौबा उस समय रक्षा का हथियार है जब इंसान की बुराइयां हमला करें। तौबा उस समय सही रास्ते पर लगाने वाला मार्गदर्शक है जब वासना हमला करे। 'तौबा का दरवाज़ा उनके लिए खोला गया ताकि वे तौबा करें। बेशक अल्लाह तौबा क़बूल करने वाला और दयावान है' (तौबा, 118)। 'तौबा का दरवाज़ा खुला' कहने का क्या अर्थ है? यानी बंदों को तौबा की ओर मोड़ने के लिए उन्हें मुश्किल में डालता है। यदि अल्लाह उनकी सेहत को लगातार बनाए रखता और उनकी संपत्ति को लगातार बढ़ाता, तो वे अपनी वासनाओं में डूब जाते। लेकिन लोगों के तौबा करने के लिए, वह उन्हें कठिनाई और मुश्किल में डालता है। अल्लाह की रहमत की कोई सीमा नहीं। यदि वह बंदों को गुनाह, नाफ़रमानी और हराम लज़्ज़तों में पड़ा रहने देता, तो वे जहन्नमी बन जाते। लेकिन अल्लाह उस बंदे पर रहम करते हुए उसे मुसीबत में डालता है ताकि वह तौबा करे। फिर अत-तव्वाब सिफ़त से वह उस बंदे के गुनाहों को बहुत अधिक माफ़ कर देता है।","अत्याचारियों और नाफ़रमानों से बदला लेने वाला। यदि अल-मुंतक़िम शब्द किसी इंसान के लिए इस्तेमाल किया जाए, तो हम उसे उचित नहीं समझेंगे। लेकिन अल्लाह के लिए इस्तेमाल किया जाए, तो यह पूरी तरह से सुंदर अर्थ ग्रहण करता है। इसलिए यह 'अल्लाह के सुंदर नामों' में गिना गया है। अल्लाह अत्याचारी से बदला लेकर उसे दूसरों को नुकसान पहुंचाने से रोकता है और उसके ज़ुल्म को समाप्त करता है। अल-मुंतक़िम शब्द का अर्थ है दंड देना। अल्लाह अनुशासन के लिए दंड देता है, खुशी के लिए अनुशासित करता है। यदि तुम दुनियावी ज़िंदगी में किसी अपराधी से मिलो जिसने हत्या की हो, चोरी की हो और जो चाहा किया हो, लोगों को नुकसान पहुंचाकर, और उसे पकड़कर जेल में डाल दिया जाए, तो लोग उसके क़ैद होने से सुकून और राहत महसूस करते हैं। बदला और दंड इस अर्थ में अल्लाह की पूर्णता के गुण के लायक है। कभी-कभी तुम कहोगे: 'पता चला कि अगर इस इंसान के साथ कुछ किया जाए, तो वह बेहतर हो जाता है।' दरअसल, अल्लाह उसे कोई दंड देकर उस बुरे इंसान को अविश्वसनीय स्तर तक अच्छा बना देता है। 'हमने तुमसे पहले भी पैगंबरों को उनकी क़ौमों के पास भेजा। उन्होंने स्पष्ट प्रमाण पेश किए। फिर हमने अपराधियों से बदला लिया। मोमिनों की मदद करना हम पर वाजिब था' (रूम, 47)। 'तो हमने उनसे बदला लिया। अब देखो, झुठलाने वालों का अंजाम क्या हुआ?!' (ज़ुख़रुफ़, 25)।","क्षमा करने वाले के अर्थ में है। इस महान नाम के बारे में बात करने से पहले, आइए तौबा और क्षमा के बारे में बात करें। अल्लाह ने अपने बंदों के लिए तौबा का दरवाज़ा खोला, क्योंकि अल्लाह उनकी गलतियों और नेकियों, अच्छे और बुरे कार्यों को जानता है। उन्हें बनाते समय, अल्लाह ने उन्हें वासना के साथ भी बनाया। यदि यह वासना अल्लाह की ओर निर्देशित न हो और अल्लाह से आने वाले नूर के साथ न जुड़े, तो यह अपने मालिक को बर्बाद कर देगी। यदि अल्लाह ने तौबा का दरवाज़ा न खोला होता, तो इंसान की बुराई और बढ़ जाती और वह अल्लाह की दया से निराश हो जाता। इसलिए अल्लाह ने कहा: 'कह दो: ऐ मेरे बंदो, जिन्होंने अपनी जानों पर ज़्यादती की है, अल्लाह की दया से निराश न हो। बेशक अल्लाह सभी गुनाहों को माफ करता है। बेशक वही अत्यंत क्षमाशील, अत्यंत दयावान है' (ज़ुमर, 53)। 'अफ़्व' शब्द का शाब्दिक अर्थ हटाना, मिटाना भी है। इस प्रकार, 'अफ़्व' शब्द बुराइयों को मिटाता है और गुनाहों को माफ करता है। यह अल-ग़फ़ूर नाम के क़रीब है, लेकिन उससे अधिक शक्तिशाली है। क्योंकि मग़फ़िरत (क्षमा) बुराई की खबर छोड़ते हुए माफ करती है। अफ़्व, इसके विपरीत, इसके पूर्ण मिटने की खबर देता है। अफ़्व में, इसे लिखने वाले फ़रिश्तों की याददाश्त और पन्ने भी इसे भूल जाते हैं। तुमने एक गुनाह किया, लेकिन हमारे रब ने उसे माफ़ कर दिया और तुम्हें सज़ा नहीं दी। फिर भी वह गुनाह तुम्हें तकलीफ़ देता और बेचैन करता रहता है, और जब याद आता है तो तुम अल्लाह से शर्मिंदा होते हो। लेकिन यदि वह अफ़्व कर दे, तो तुम्हारा गुनाह तुम्हारे सहीफ़े से पूरी तरह मिट जाता है, मग़फ़िरत की हवा उसे ख़त्म कर देती है और वह फ़रिश्तों के दफ़्तर से भी मिटा दिया जाता है। 'अफ़्व' शब्द क़ुरआन करीम में उनतालीस से अधिक जगहों पर आया है। साल में एक बार आने वाली, हज़ार महीनों से बेहतर सबसे महान शब-ए-क़द्र में अल्लाह के रसूल सल्लल्लाहु अलैहि वसल्लम ने यह कहने का हुक्म दिया: 'अल्लाहुम्मा इन्नका अफ़ुव्वुन तुहिब्बुल अफ़्वा फ़अ्फ़ु अन्ना' ('ऐ अल्लाह, तू माफ़ करने वाला है, माफ़ करना पसंद करता है, हमें माफ़ कर दे')।","अत्यंत दयालु और कोमल, दया की सर्वोच्च डिग्री। कुछ लोग पूछ सकते हैं: 'अल्लाह के नाम अर-रहीम — दयालु, और अर-रऊफ — कोमल के बीच क्या अंतर है?' जवाब यह है कि यदि किसी पर मुसीबत आ जाए, तो अल्लाह उस पर दया करता है। लेकिन उसकी कोमलता यह है कि मुसीबत आने से पहले ही उसे सभी बुराइयों से दूर रखे। कभी-कभी अर-रऊफ नाम सुरक्षा और बुराई को रोकने के लिए आता है, जबकि अर-रहीम नाम उपचार के लिए आता है। अल्लाह का तीव्र दया दिखाना उसकी कोमलता के कारण है। उसकी कोमलता के कारण, वह बंदे को गुनाह में पड़ने से पहले तौबा के लिए बुलाता है। यदि वे गुनाह में पड़ ही जाएं, तो वे दंड के हक़दार बन जाते हैं। 'ऐ हमारे रब, बेशक तू दयालु और कोमल है' (हश्र, 10)। इस नाम के संबंध में उचित आचरण यह है कि हमें अल्लाह के प्रेम के लिए इसे बार-बार याद करना चाहिए। यदि हम इस नाम से चरित्रित होना चाहते हैं, तो हमें लोगों को गुनाह में पड़ने से रोकना चाहिए। यहां हमें इलाज नहीं बल्कि बीमारी की रोकथाम में लगना चाहिए। विशेष रूप से हमारे बच्चों में इसे लागू करना महत्वपूर्ण है।","साम्राज्य का स्वामी। वह इस दुनिया के मामलों को जैसे चाहे संचालित करता है। उसके फैसले को पलटने वाला और उसके हुक्म को बदलने वाला कोई नहीं। क़ुरआन करीम में यह नाम अल-मलिक, अल-मालिक, अल-मलीक और मालिकुल-मुल्क के रूप में आता है। 'कहो: ऐ साम्राज्य के मालिक अल्लाह! तू जिसे चाहे साम्राज्य दे और जिससे चाहे साम्राज्य छीन ले, जिसे चाहे इज़्ज़त दे और जिसे चाहे ज़िल्लत दे। सारी भलाई तेरे हाथ में है। बेशक तू हर चीज़ पर सक्षम है' (आल इमरान, 26)। इमाम ग़ज़्ज़ाली ने कहा मालिकुल-मुल्क का अर्थ है: 'अपने साम्राज्य में, यानी अपने राज्य में, जैसे चाहे अपनी इच्छा को अंजाम देने वाला।' कुछ मुफ़स्सिरों ने कहा मालिकुल-मुल्क का अर्थ है 'साम्राज्य का सच्चा स्वामी'। इसलिए हदीस कुद्सी में अल्लाह ने कहा: 'मैं बादशाहों का मालिक और स्वामी हूं। बादशाहों के दिल मेरे नियंत्रण में हैं। यदि बंदे मेरी इताअत करें, तो मैं बादशाहों के दिलों को उनकी ओर दया और भलाई से मोड़ता हूं। यदि बंदे नाफ़रमानी करें, तो मैं बादशाहों के दिलों को उनके ख़िलाफ़ क्रोध और ग़ुस्से से मोड़ता हूं। तुम अपने बादशाहों को कोसने में व्यस्त न रहो, बल्कि उनके सुधार के लिए दुआ करो, क्योंकि उनकी भलाई तुम्हारी भलाई से जुड़ी है।'","गौरव और उदारता के स्वामी। सम्मान और अनुदान के स्वामी। हम अल्लाह के नामों को दो भागों में बांट सकते हैं। एक भाग उसकी शक्ति की ओर इशारा करता है, दूसरा भाग उसकी पूर्णता की ओर। पूर्णता के सभी प्रकार 'अल-इकराम' नाम में समाहित हैं। शक्ति की सभी अभिव्यक्तियां 'ज़ुल-जलाल' नाम में समाहित हैं। यह नाम क़ुरआन करीम में दो जगह आया है — सूरह अर-रहमान की आयत 27 और 78। इमाम राज़ी ने कहा: 'अल-इकराम' अनुदान के अर्थ के क़रीब है, लेकिन अल-इकराम का अर्थ अधिक विशिष्ट है। क्योंकि अल्लाह उस व्यक्ति को भी नेमत दे सकता है जिसे वह सम्मानित नहीं करता। उदाहरण के लिए, अल्लाह काफ़िर को पसंद नहीं करता। फिर भी वह उसे धन, स्वास्थ्य, संतान, घर और सवारी अता करता है। इस प्रकार, यह सब अनुदान है, सम्मान नहीं। लेकिन जो वह मोमिनों को देता है वह सम्मान है। अल्लाह का सम्मान दो प्रकार का है। पहला दुनिया में जल्दी आने वाला सम्मान। दूसरा आख़िरत के लिए टाला गया सम्मान। रिवायतों के अनुसार, 'ज़ुल-जलालि वल-इकराम' नाम 'इस्मे आज़म' में से है। अनस रज़ियल्लाहु अन्हु से रिवायत है: एक व्यक्ति ने नमाज़ पढ़ी फिर दुआ की: 'अल्लाहुम्मा इन्नी अस्अलुका बिअन्ना लकल हम्दु ला इलाहा इल्ला अंतल मन्नानु बदीउस्समावाति वल्अर्ज़ि या ज़ल जलालि वल इकराम या हय्यु या क़य्यूम।' तब रसूलुल्लाह सल्लल्लाहु अलैहि वसल्लम ने कहा: 'निश्चय ही उसने अल्लाह से इस्मे आज़म से दुआ की। यदि इसके साथ दुआ की जाए, तो क़बूल होती है। और यदि इसके साथ मांगा जाए, तो दिया जाता है।'","मज़लूमों को न्याय से मदद देने वाला और अत्याचारियों को न्याय से दंड देने वाला। यदि यह गुण अल्लाह के लिए इस्तेमाल किया जाए, तो इसका अर्थ है उसके निर्णय में न्याय। ज़ुल्म के बहुत सारे प्रकार हैं। ज़ुल्म क़यामत के दिन का अंधेरा है। यदि तुम्हारी ताक़त तुम्हें लोगों पर ज़ुल्म करने के लिए प्रेरित करती है, तो अपने ऊपर अल्लाह की शक्ति को याद करो। इंसान का ज्ञान जितना मज़बूत होता है, अल्लाह का डर भी उतना मज़बूत होता जाता है। लेकिन यदि कोई बंदा शक्ति से भरा हुआ 'मैं जो चाहूं करूंगा' कहकर अन्यायपूर्ण शक्ति का इस्तेमाल करने लगे, तो वह अल्लाह के प्रकोप का शिकार हो जाता है। अल-मुक़्सित का अर्थ है 'मज़लूम को अत्याचारी से उसका हक़ वापस दिलाने वाला'। अल्लाह ने कहा: 'यदि तुम फैसला करो, तो उनके बीच न्याय से फैसला करो। बेशक अल्लाह न्याय करने वालों को पसंद करता है' (माइदा, 42)। कभी-कभी तुम किसी को अंधाधुंध प्यार कर सकते हो, वहीं किसी और को अंधाधुंध नापसंद कर सकते हो। लेकिन इंसाफ की मांग है कि तुम न्याय से प्यार करो और न्याय से नापसंद करो। मेरे एक दोस्त ने कहा: 'मेरे दो बेटे हैं, एक फासिक़ और दूसरा नेक। मैं नेक बेटे को फासिक़ से ज़्यादा हिस्सा देता हूं।' मैंने बिना हिचकिचाए कहा: 'ऐसा मत करो! यदि तुम दूसरे पर ज़ुल्म करोगे, तो तुम उसके गुनाह में बने रहने और नाफ़रमान बनने का कारण बनोगे। तुम दोनों के बीच न्यायपूर्ण रहो, तब तुम जो दोगे उसमें भी बरकत होगी।' बरकत के बारे में एक हदीस में कहा गया है: 'जो अपनी नमाज़ वक़्त पर न पढ़े, अल्लाह उसकी ज़िंदगी से बरकत हटा देता है। अल्लाह के नज़दीक सबसे अच्छा अमल वक़्त पर पढ़ी गई नमाज़ है।'","एकत्र करने वाला। सभी सत्यों को एकत्र करने वाला। क़यामत के दिन लोगों को एकत्र करने वाला। इसे एकत्र करने का दिन कहने का कारण यह है कि उस दिन अल्लाह अत्याचारी और मज़लूम, शक्तिशाली और कमज़ोर, देने वाले और लेने वाले, अहंकारी और विनम्र को एक-दूसरे से हक़ वापस दिलाने के लिए इकट्ठा करता है। उस दिन, आज्ञापालन और इबादत करने वालों को पुरस्कृत करने और गुनहगारों को दंड देने के लिए, वह सृष्टि को शुरू से अंत तक, जिन्न और इंसानों को, आसमान और ज़मीन के निवासियों को इकट्ठा करता है। अल-जामिअ का अर्थ है कि अल्लाह अपनी ज़ात, गुणों और कार्यों में सभी पूर्णता को अपने में समेटता है। अल-जामिअ को यह भी समझा जाता है कि वह पुनरुत्थान के दिन मैदान-ए-महशर में टुकड़ों में विभाजित हुई सृष्टि को इकट्ठा करेगा। कभी-कभी, यदि कोई अपनी कोई चीज़ खो दे, तो वे दुआ करते हैं: 'ऐ अल्लाह, निश्चय ही किसी दिन लोगों को इकट्ठा करने वाले! मुझे मेरी ज़रूरत के साथ इकट्ठा कर दे।' और यदि अल्लाह चाहे, तो उनकी ज़रूरत पूरी हो जाती है। अल-जामिअ नाम क़ुरआन करीम की कई आयतों में आया है। आल इमरान सूरह की आयत 9 में कहा गया है: 'हमारे रब! तू निश्चय ही एक दिन लोगों को इकट्ठा करने वाला है, जिसमें कोई शक नहीं। बेशक अल्लाह वादे के ख़िलाफ़ नहीं करता।' इस नाम से बंदे के आचरण के बारे में इमाम ग़ज़्ज़ाली ने कहा: 'यह अंगों में बाहरी शिष्टाचार और दिलों में आंतरिक सत्यों को एकत्र करना है। जिसकी पहचान पूर्ण हो, उसका आचरण भी सुंदर होता है। इस स्थिति को एकत्र करने वाला कहा जाता है।'","किसी की ज़रूरत नहीं। उसे किसी की और किसी चीज़ की ज़रूरत नहीं। सृष्टिकर्ता की विशेषता यह है कि वह हर चीज़ में बेनियाज़ है। सृष्टि की विशेषता यह है कि वह हर चीज़ की मुहताज है। अल्लाह ने मुहम्मद सूरह की आयत 38 में कहा: 'अल्लाह बेनियाज़ है और तुम मुहताज हो।' अक्सर क़ुरआन में 'अल-ग़नी' (बेनियाज़) शब्द 'अल-हमीद' (प्रशंसित) शब्द के क़रीब आता है। क्योंकि अल्लाह अपने बंदों का मुहताज नहीं, साथ ही सृष्टि उसकी प्रशंसा करती है। लेकिन इंसान धनवान होकर किसी की ज़रूरत के बिना बेनियाज़ हो सकता है, फिर भी वह उद्दंड, अहंकारी, घमंडी और नापसंद व्यक्ति बन सकता है। लेकिन ज़मीन-आसमान का सृष्टिकर्ता संपूर्ण और बेनियाज़ है। अल्लाह स्वयं बेनियाज़ है, साथ ही सृष्टि को भोजन, पेय और वायु से पोषित करता है। इंसान का बेनियाज़ होना सापेक्ष है। क्योंकि इंसान बेनियाज़ होने के साथ-साथ असंख्य चीज़ों का मुहताज भी होता है। अल्लाह अपनी सृष्टि से अपनी ज़ात, गुणों और शासन में बेनियाज़ है। सारी सृष्टि उसके उपकार और अनुग्रह की मुहताज है। वह पूर्ण और सच्चे अर्थ में बेनियाज़ है। अल्लाह के इस गुण से चरित्रित होने का अर्थ है हमेशा उसके सामने अपनी ग़रीबी और ज़रूरत ज़ाहिर करना, और कोई काम पूरा करने पर यह न कहना 'मैंने इसे अपनी अक्ल या ज्ञान से किया', बल्कि यह कहना 'मैंने इसे अल्लाह के फ़ज़्ल, मदद और तौफ़ीक़ से हासिल किया'।","समृद्ध करने वाला, मुहताजी से मुक्त करने वाला। वह अपने बंदों में से जिसे चाहे मुहताजी से मुक्त कर देता है। तुम कुछ लोगों को देखते हो जो अत्यंत तेज़ और बुद्धिमान होने के बावजूद कोई माल-दौलत नहीं रखते। तुम कुछ अन्य लोगों को देखते हो जो सरल और साधारण होने के बावजूद पूर्ण प्रचुरता रखते हैं। यही अल्लाह का अल-मुग़नी नाम है, जिसका अर्थ समझा जाता है कि वह जिसे चाहे मुहताजी से मुक्त करता है। अल-मुग़नी अपने बंदों को स्वयं की पहचान से मुहताजी से मुक्त करता है। मसलन, रबीआ ने नबी (सल्लल्लाहु अलैहि वसल्लम) की कई दिनों तक सेवा की। उन्होंने कहा, 'अगर तुम्हें कोई ज़रूरत हो, तो मांगो।' रबीआ ने कहा, 'मुझे थोड़ा समय दें।' कुछ दिनों बाद उन्होंने पूछा, 'ऐ रबीआ, क्या हुआ?' उसने जवाब दिया, 'मैं आपके साथ जन्नत में साथी बनने की मांग करता हूं।' उन्होंने पूछा, 'तुम्हें यह किसने सिखाया?' उसने जवाब दिया, 'अल्लाह की क़सम, मुझे किसी ने नहीं सिखाया। लेकिन यह जानते हुए कि दुनिया नश्वर है और इसका कोई वास्तविक मूल्य नहीं, मैंने बस जन्नत में शाश्वत निवास और आपके साथ जन्नत में रहने की मांग की।' अल्लाह ने उस व्यक्ति को यह बताया और उसे मुहताजी से मुक्त कर दिया। अल्लाह कभी-कभी धन, कभी ज्ञान, कभी स्वास्थ्य, कभी नेक पत्नी या कभी निवास के माध्यम से मुहताजी से मुक्त करता है। जिब्रील अलैहिस्सलाम इब्राहीम अलैहिस्सलाम के पास (आग में डाले जाने के समय) आए और पूछा, 'क्या तुम्हें कोई ज़रूरत है?' इब्राहीम अलैहिस्सलाम ने कहा, 'आपसे?' जिब्रील अलैहिस्सलाम ने कहा, 'नहीं, अल्लाह से।' इब्राहीम अलैहिस्सलाम ने कहा, 'मेरे हाल से उसका वाक़िफ़ होना ही मुझे मांगने से बेनियाज़ कर देता है।'","रोकने वाला। रक्षक के अर्थ में भी आता है। वह तुम्हें दुश्मन, विरोधी, बुराई के आगमन, हानिकारक चीज़ों तथा दीन और दुनिया की बाधाओं से बचाता है। सुरक्षित महसूस करना एक अद्भुत भावना है, जिसका अर्थ है कि इंसान अल्लाह की सुरक्षा और शरण में है। कभी-कभी इंसान सबसे आधुनिक वाहन में बैठकर यात्रा करता है, लेकिन अपनी मंज़िल तक नहीं पहुंच पाता। कभी-कभी, पुराना वाहन चलाते हुए, वे सुरक्षित अपनी मंज़िल तक पहुंच जाते हैं। वे अपने भीतर सुरक्षा और शांति महसूस करते हैं क्योंकि वे सुरक्षा में हैं। अल्लाह मुशरिकों के दिलों में डर डालता है क्योंकि उन्होंने शिर्क किया। एक मोमिन बंदा, इसके विपरीत, हमेशा उच्च आत्मा और उदात्त भावना में जीता है। क्योंकि वह अल-मानिअ गुण वाली सत्ता की सुरक्षा में है। वह उसे दुश्मनों और विरोधियों से बचाता है। नबी (सल्लल्लाहु अलैहि वसल्लम) बनू नज़ीर क़बीले के पास उनके बीच के समझौते को याद दिलाने के लिए गए और एक जगह बैठ गए। वहां मौजूद लोगों ने साज़िश रचकर ऊपर से एक बड़ा पत्थर गिराकर रसूलुल्लाह को मारने का फैसला किया। उसी क्षण वही उतरी और उन्हें इस बारे में सूचित किया। रसूलुल्लाह अपनी जगह से उठे और चले गए और मृत्यु से सुरक्षित रहे। इस नाम से चरित्रित व्यक्ति को अल्लाह के अलावा किसी और से नहीं मांगना चाहिए, क्योंकि देने वाला और रोकने वाला दोनों वही अकेला है।","जिसे चाहे नुकसान पहुंचाने वाला। अद-दार्र 'फ़ायदा' शब्द का विपरीत है। इंसान कब मुनाफ़िक़त करता है या कब दिखावा करता है या कब डरता है या कब सिर झुकाता है या कब अपमानित होता है? जब वह यह मानता है कि उसके जैसा कोई इंसान उसे फ़ायदा या नुकसान पहुंचा सकता है, तो वह इन चीज़ों का सामना करता है। लेकिन यदि वह मानता है कि फ़ायदा और नुकसान दोनों केवल अल्लाह देता है, तो वह सिर ऊंचा उठाकर इज़्ज़त से चलता है। सभी शक्ति, इज़्ज़त और साहस का कारण यह विश्वास है कि अल्लाह के अलावा कोई फ़ायदा या नुकसान पहुंचाने वाला नहीं। मोमिन बंदा अल्लाह के फ़ैसले के सामने समर्पित होता है और उसके रास्ते में सब्र करता है। यदि मोमिन अल्लाह के फ़ैसले पर सब्र करे, तो अल्लाह उसके दिल में सुकून डाल देता है। अल्लाह के नुकसान पहुंचाने को कैसे समझा जाए? मसलन, एक सर्जन अपने बच्चे से चाहे कितना भी प्यार करे, यदि बच्चे को अपेंडिसाइटिस हो जाए, तो वह बेहोशी की दवा देकर, सर्जिकल चाकू से पेट चीरकर, दर्द देते हुए अपेंडिक्स निकाल देता है। लेकिन पिता यह सिर्फ अपने बच्चे की सेहत के लिए करता है। अल्लाह के नुकसान पहुंचाने को भी बिल्कुल इसी अर्थ में समझा जाना चाहिए। अल्लाह ने इस बारे में कहा: 'अल्लाह के सुंदर नाम हैं, तो उसे उन नामों से पुकारो और उसके नामों में टेढ़ापन करने वालों को छोड़ दो' (आराफ, 180)। इस नाम में बंदे का हिस्सा यह है कि मोमिन को गुमराह लोगों से दूर रहना चाहिए, ताकि वह अल्लाह के बंदों को फ़ायदा पहुंचाए और नुकसान न पहुंचाए। साथ ही अल्लाह के अलावा किसी और से उम्मीद न रखना, किसी से न डरना और पूरी तरह अल्लाह पर भरोसा करके समर्पित होना।","फ़ायदा देने वाला। अन-नाफ़िअ 'नुकसान' शब्द का विपरीत है। इंसान कब मुनाफ़िक़त करता है या कब दिखावा करता है या कब डरता है या कब सिर झुकाता है या कब अपमानित होता है? जब वह यह मानता है कि उसके जैसा कोई इंसान उसे फ़ायदा या नुकसान पहुंचा सकता है, तो वह इन चीज़ों का सामना करता है। लेकिन यदि वह मानता है कि फ़ायदा और नुकसान दोनों केवल अल्लाह देता है, तो वह सिर ऊंचा उठाकर इज़्ज़त से चलता है। कई धार्मिक स्रोतों में 'अद-दार्र' और 'अन-नाफ़िअ' नामों का एक साधारण कारण से एक साथ प्रयोग किया जाना ज़रूरी है। वह साधारण कारण यह है कि अल्लाह फ़ायदा पहुंचाने के लिए नुकसान पहुंचाता है। यानी, यदि वह कुछ लोगों को गंभीर बीमारी या आर्थिक कठिनाई में डालता है, तो यह इसलिए है ताकि वह बंदा अल्लाह की ओर लौटे और तौबा करे। कुछ आरिफ़ दुआ करते थे: 'ऐ अल्लाह! मैं तेरे नाम अन-नाफ़िअ को गवाह बनाकर मांगता हूं। तेरे सिवा किसी और पर भरोसा नहीं करूंगा, ऐ वली और वासिअ नाम वाली सत्ता!' कुछ उलमा ने कहा: 'अद-दार्र' और 'अन-नाफ़िअ' ये दोनों नाम और गुण हैं जो संपूर्ण ईश्वरीय शक्ति की ओर इशारा करते हैं। कोई नुकसान पहुंचाने वाला, फ़ायदा देने वाला, बुराई पहुंचाने वाला और भलाई करने वाला नहीं, सिवाय अल्लाह की इच्छा से।' अल्लाह ने कहा: 'कहो, सब कुछ अल्लाह की ओर से है' (निसा, 78)। इमाम क़ुशैरी ने कहा: 'अद-दार्र और अन-नाफ़िअ नाम अल्लाह के सुंदर नामों में से हैं, और दोनों के अर्थ में तौहीद की ओर इशारा है।' क़ुरआन करीम के आराफ सूरह की आयत 188 में कहा गया है: 'कहो: मैं अपने लिए भी किसी फ़ायदे या नुकसान का मालिक नहीं, सिवाय जो अल्लाह चाहे। अगर मुझे ग़ैब का ज्ञान होता, तो मैं बहुत भलाई जमा कर लेता और मुझे कोई बुराई न छूती। मैं तो बस ईमान लाने वाली क़ौम के लिए एक चेतावनी देने वाला और खुशख़बरी सुनाने वाला हूं।'","स्वयं अपने आप में प्रकट और दूसरों को प्रकट करने वाला। 'नूर' शब्द का शाब्दिक अर्थ है चमक और प्रकाश। अल्लाह क़ुरआन करीम के माध्यम से जीवन का सत्य सिखाता है, हलाल-हराम, अच्छे-बुरे, सत्य-असत्य को स्पष्ट करता है। सूरह माइदा की आयत 15 में कहा गया है: 'तुम्हारे पास अल्लाह की ओर से एक प्रकाश और स्पष्ट किताब आ चुकी है।' इस प्रकार, यह क़ुरआन ही प्रकाश है। प्रकाश दो प्रकार का होता है: 1. तार्किक। 2. विशेष। सूरज और चांद के प्रकाश जैसी चमक को विशेष प्रकाश कहा जाता है। ईश्वरीय शिक्षा से युक्त क़ुरआन को तार्किक प्रकाश कहा जाता है। तुम्हारी आंखों को चीज़ें देखने के लिए सूरज के प्रकाश की ज़रूरत है। तुम्हारी बुद्धि को चीज़ों का सत्य जानने के लिए अल्लाह के प्रकाश की ज़रूरत है। इंसान चाहे कितना भी तेज़ और प्रतिभाशाली क्यों न हो, यदि उसे अल्लाह के प्रकाश से मदद न मिले, तो वह वास्तव में अंधा है। अल्लाह ने खुद को प्रकाश कहा, क्योंकि प्रकाश उसी से है। वह क्षितिजों को सितारों से, शरीरों को इबादत के निशानों से और दिलों को प्रमाण और तर्कों से रोशन करता है। यदि इंसान अल्लाह से जुड़ जाए, तो उसके चेहरे पर प्रकाश दिखाई देता है। नबी (सल्लल्लाहु अलैहि वसल्लम) उस प्रकाश को पाने के लिए यह दुआ पढ़ते थे: 'अल्लाहुम्मज्अल फी क़ल्बी नूरन व फी लिसानी नूरन वज्अल फी समई नूरन वज्अल फी बसरी नूरन' ('ऐ मेरे रब, मेरे दिल में नूर कर दे, मेरी ज़बान में नूर कर दे, मेरे कान में नूर कर दे, मेरी आंख में नूर कर दे')।","मार्गदर्शन करने वाला। वह अपनी कृपा से जिसे चाहे मार्गदर्शन देता है। हिदायत का अर्थ है सही रास्ते की ओर निर्देशित करना। यदि तुम धरती और आसमान की सृष्टि पर विचार करो, तो तुम अल्लाह की पहचान की ओर एक बड़ा क़दम उठाते हो। ब्रह्मांड हमें उसकी ओर मार्गदर्शन करता है। हिदायतों में सबसे पहला और सबसे महान यह है कि ब्रह्मांड में अल्लाह के ज्ञान, हिकमत, शक्ति, धन और सहनशीलता को देखना। अल्लाह ने तुम्हें सूंघने की इंद्रिय से सुसज्जित किया है। अल्लाह ने तुम्हें सोचने की क्षमता, ज्ञान और अनुभव, पांच इंद्रियां दी हैं। अल्लाह ने सभी जानवरों को सहज प्रवृत्ति के ज़रिए उनके अपने फ़ायदे की ओर निर्देशित किया है। हिदायत चार प्रकार की होती है। पहली, सामान्य हिदायत है, जो इंसान को भोजन, वस्त्र, घर बनाने जैसी सामान्य हिदायत देती है। दूसरी, ईमान की हिदायत है, जो ईमान और हक़ की ओर बुलाने वाले क़ुरआन की ओर मार्गदर्शन करती है। तीसरी, तौफ़ीक़ की हिदायत है, जिसके बारे में अल्लाह ने कहा: 'हम तुम्हें उनकी हक़ीक़त सुनाते हैं। बेशक वे ऐसे नौजवान थे जो अपने रब पर ईमान लाए, और हमने उनकी हिदायत और बढ़ा दी' (कहफ़, 13)। चौथी, जन्नत की हिदायत है, जिसके बारे में अल्लाह ने कहा: 'अल्लाह के रास्ते में मारे गए लोगों के अमल वह कभी बर्बाद नहीं करेगा। वह उन्हें हिदायत देगा और उनकी हालत सुधारेगा। और उन्हें उस जन्नत में दाख़िल करेगा जो उसने उन्हें बताई है' (मुहम्मद, 46)। 'अल्लाह से डरो और अल्लाह तुम्हें सिखाएगा। अल्लाह हर चीज़ को जानने वाला है' (बक़रा, 282)।","अद्वितीय चीज़ों को बनाने वाला। लेकिन यदि इंसान कुछ ईजाद करता है, तो निस्संदेह वह अल्लाह की सृष्टियों की नकल करता है। जो किसी काम को सबसे पहले करे जो पहले किसी ने न किया हो, उसे अरबी में 'अब्दआ' कहा जाता है। 'बिदअत' शब्द भी इसी शब्द से लिया गया है। बिदअत के दो अर्थ हैं। शाब्दिक अर्थ में हर नई चीज़ को बिदअत कहा जाता है। शरीअत में, दीन में न होने वाली चीज़ को नया बनाना बिदअत कहलाता है। दीन में बिदअत को अंजाम देना हराम अमल है। अल-बदीअ नाम में अक़ीदे, इबादत और सुलूक में नयापन न करने की पुकार है। क्योंकि दीन में नयापन पैदा करने वाला एक सुन्नत को छोड़ने के बदले में नयापन पैदा करता है। उलमा ने बिदअत की परिभाषा में कहा: 'यह वह चीज़ है जिसकी अल्लाह की किताब, उसके रसूल की सुन्नत और उम्मत के इज्मा में कोई असल नहीं।' हमें अल्लाह की सृष्टियों में नयापन और आविष्कार करने की अनुमति है। मसलन, खेती, वनस्पति, पशुपालन, रंग बनाना, धातुओं को मिलाना जैसी चीज़ों में नयापन करना और आविष्कार करना जायज़ है। लेकिन दीन में नयापन करने का हमें बिल्कुल हक़ नहीं। 'अल-बदीअ' शब्द का एक और अर्थ है कि उसका कोई सानी नहीं, कोई समान नहीं, न उसकी ज़ात में, न उसके गुणों में, न उसके कार्यों में, न उसकी सृष्टि में उसके जैसा कुछ नहीं है। अल्लाह ने हर चीज़ को न-होने से बनाया। इस नाम में बंदे का हिस्सा बिदअती न बनना है।","सदा बाक़ी रहने वाला। वह हमेशा मौजूद है, फ़ानीपन उसे नहीं छूता। इस प्रकार, बक़ा फ़ानीपन का विपरीत है। अल्लाह की बाक़ी रहने वाली चीज़ों से मतलब है अल्लाह की इताअत करना और उसके सवाब की प्रतीक्षा करना। कभी-कभी इताअत और इबादत मुश्किल और कठिन होती है, लेकिन उसकी मुश्किलें दूर हो जाती हैं जबकि उसका सवाब हमेशा बाक़ी रहता है। जबकि शहवानी सुख मिट जाता है, लेकिन उसकी सज़ा हमेशा बाक़ी रहती है। अल-बाक़ी का एक और अर्थ है बाक़ी रहने वाले नेक अमल। 'माल और औलाद दुनिया की ज़िंदगी की ज़ीनत हैं। बाक़ी रहने वाले नेक अमल तुम्हारे रब के नज़दीक सवाब और उम्मीद के लिहाज़ से बेहतर हैं' (कहफ़, 46)। 'सुभानल्लाहि वल-हम्दुलिल्लाहि वला इलाहा इल्लल्लाहु वल्लाहु अकबर' कहना भी बाक़ी रहने वाले नेक अमलों में शामिल है। वास्तव में, अल-बाक़ी से केवल अल्लाह ही समझा जाता है। जब हमारे नबी (सल्लल्लाहु अलैहि वसल्लम) का इंतक़ाल हुआ, तो अबू बक्र सिद्दीक़ ने कहा: 'जो मुहम्मद की इबादत कर रहा था, वह इंतक़ाल कर गए। जो अल्लाह की इबादत कर रहा था, अल्लाह ज़िंदा है, वह नहीं मरता।' अल्लाह बाक़ी है। बक़ा का गुण ज़ाती गुणों में से है। इमाम ग़ज़्ज़ाली ने कहा: 'अल-बाक़ी का अर्थ है कि वह अपनी ज़ात में वाजिबुल वुजूद है।' यदि वाजिबुल वुजूद भविष्य से जोड़ा जाए, तो वह बाक़ी रहने वाला बनता है; अगर अतीत से जोड़ा जाए, तो वह क़दीम बनता है। इमाम राज़ी ने कहा: 'अल्लाह तआला वाजिबुल वुजूद है, यानी उसके लिए ख़त्म होना मुनासिब नहीं।' अल-बाक़ी शब्द का एक और अर्थ है: 'उसके अस्तित्व में न कोई शुरुआत है, न कोई अंत।'","जब सृष्टियां न रहें, तब भी बाक़ी रहने वाली सत्ता। दुनियावी जीवन में सभी नष्ट हो जाते हैं, केवल अल-वारिस गुण वाली सत्ता जीवित रहती है। क्योंकि अल्लाह जीवित और बाक़ी है, वारिस है। माल-दौलत तुम्हारे हाथ में अमानत के तौर पर अस्थायी रूप से दी गई है। इसका उद्देश्य सिर्फ यह जांचना है कि तुम कौन सा रास्ता अपनाते हो। 'तुम अल्लाह की राह में इन्फ़ाक़ क्यों नहीं करते?! जबकि आसमानों और ज़मीन की विरासत तो अकेले अल्लाह की है' (हदीद, 10)। नबी (सल्लल्लाहु अलैहि वसल्लम) ने दिरहम और दीनार विरासत में नहीं छोड़े, उन्होंने इस दीन का ज्ञान विरासत में छोड़ा। जो यह ज्ञान हासिल करे, उसने पूरा हिस्सा हासिल किया। क़यामत के दिन अल्लाह पुकारेगा: 'सारी बादशाहत किसकी है?' सारी सृष्टि जवाब देगी: 'अल-वाहिद और अल-क़हार गुण वाले अल्लाह की।' हर 50 साल में अचल संपत्ति, दुकानें और खेती की ज़मीनें नए मालिकों में बदल जाती हैं। यह तब तक जारी रहता है जब तक अल्लाह अकेले ज़मीन-आसमान का वारिस नहीं बन जाता। इस नाम से हमारा संबंध यह है कि हमारे हाथ में मौजूद चीज़ें हमारी नहीं हैं, बल्कि वे दूसरों को हस्तांतरित हो जाएंगी, और अंत में अल्लाह खुद उनका वारिस बनेगा। हमें यह केवल अमानत के तौर पर दिया गया है, हम बस उसके प्रबंधक हैं, और एक दिन इसके बारे में हमसे सख़्त सवाल किया जाएगा।","सही रास्ते की ओर मार्गदर्शन करने वाला। अर-रशीद गुण, यदि अल्लाह के लिए इस्तेमाल हो, तो इसका मतलब है पूर्ण रूप से सही रास्ते की ओर ले जाने वाला। अल्लाह का ज्ञान, शक्ति और दया पूर्ण है। यदि इंसान यह विश्वास करे कि अल्लाह के गुण पूर्ण हैं और सब कुछ उसके नियंत्रण में है, तो उसकी आत्मा में सुकून राज करेगा। अल्लाह अपनी कई सृष्टियों को सेहत, बुद्धिमत्ता, धन और सुंदरता देता है। लेकिन वह सुकून केवल अपने सच्चे मोमिन बंदों को देता है। बिगाड़ अल्लाह द्वारा दी गई नेमतों के ग़लत इस्तेमाल से पैदा होता है। अल्लाह अपने रशीद गुण से तुम्हें सबसे मज़बूत और सही रास्ते की ओर ले जाता है। रशीद का मतलब है सही और उचित रास्ते पर चलना, बिना भटके, बिना दाएं-बाएं झुके, शुद्ध लक्ष्य की ओर छोटे रास्ते से जाना। मोमिन इंसान की नज़र स्वस्थ होती है। क्योंकि अल्लाह ने उसके दिल में नूर रखा है। उस नूर के ज़रिए वह हक़ को हक़ मानता है, उसी हक़ रास्ते पर चढ़ता है और रशीद, यानी सही रास्ते पर चलने की खुशी हासिल करता है। 'जिसे अल्लाह हिदायत दे, वही हिदायत पाने वाला है। जिसे वह गुमराह करे, तो तुम उसके लिए हरगिज़ कोई मार्गदर्शक दोस्त नहीं पाओगे' (कहफ़, 17)। 'वह जिसे चाहे हिकमत देता है। जिसे हिकमत दी गई, उसे बहुत भलाई दी गई। केवल अक़्ल वाले ही याद रखते हैं' (बक़रा, 269)। सही रास्ते की ओर मार्गदर्शन चार प्रकार का है: 1. इंसान को फ़ायदा देने वाला मार्गदर्शन। 2. वही के ज़रिए मिलने वाला मार्गदर्शन। 3. अल्लाह की तौफ़ीक़ के ज़रिए मिलने वाला मार्गदर्शन। 4. जन्नत हासिल करने के लिए मार्गदर्शन।","अत्यंत सहनशील। नाफ़रमानों को दंड देने में जल्दबाज़ी नहीं करता। कभी-कभी, अल्लाह का इनकार करने वाले काफ़िरों को गुनाहों में डूबे और दूसरों पर ज़ुल्म करते देखकर, कमज़ोर ईमान वाले कहते हैं: 'अल्लाह कहां है? वह उन्हें दंड क्यों नहीं देता?' अल्लाह ने इस बारे में कहा: 'तुम हरगिज़ यह न समझना कि अल्लाह अत्याचारियों के कामों से बेख़बर है। वह उन्हें बस उस दिन तक मोहलत देता है जब आंखें फटी रह जाएंगी' (इब्राहीम, 42)। अल्लाह इससे बेख़बर नहीं है, वह बस इंसान को एक निश्चित ख़तरे के स्तर तक पहुंचने तक अनजान बनकर छोड़ देता है। अपनी संपूर्ण हिकमत के अनुसार, वह दंड में देरी करता है और सब्र करता है। कुछ लोग पूछ सकते हैं: 'अल्लाह के अल-हलीम और अस-सबूर गुणों में क्या अंतर है?' जवाब यह है कि अस-सबूर नाम केवल दंड में देरी पर केंद्रित है। जबकि अल-हलीम नाम दंड में देरी करता है और अंत में उसे माफ़ भी कर देता है। अल्लाह के अस-सबूर नाम में इंसान का हिस्सा अपने रब के लिए सब्र करना है। मसलन, कमज़ोर इंसान ताक़तवर इंसान के ज़ुल्म पर सब्र करता है और कहता है: 'हसबियल्लाहु व निअमल वकील' — यानी अल्लाह मेरे लिए काफ़ी है, वह कितना अच्छा वकील है। लेकिन दंड देने में सक्षम होते हुए भी माफ़ कर देना अल्लाह के लिए होने वाला और अल्लाह की ओर उठाने वाला सच्चा सब्र है। मसलन, मक्का फ़तह के दिन नबी (सल्लल्लाहु अलैहि वसल्लम) ने कुरैश से पूछा: 'तुम क्या सोचते हो मैं तुम्हारे साथ क्या करूंगा?' उन्होंने कहा: 'आप एक इज़्ज़तदार इंसान हैं और इज़्ज़तदार इंसान के बेटे हैं।' तब रसूलुल्लाह (सल्लल्लाहु अलैहि वसल्लम) ने कहा: 'जाओ, तुम आज़ाद हो', और उन्हें दंड नहीं दिया। सब्र के साथ इताअत और इबादत में रहना कामयाबी की ओर ले जाता है। सब्र के साथ गुनाह और नाफ़रमानी में पड़े रहना ज़िल्लत की ओर, फिर क़ब्र की ओर ले जाता है। अल्लाह के अस-सबूर नाम से हिस्सा पाने के लिए तुम्हें भी अपनी पत्नी, बच्चों, पड़ोसियों, रिश्तेदारों, काम के साझेदारों और अपने आसपास के सभी लोगों के साथ सब्र करना चाहिए।"]
